const formatDuration = (ms) => {
  if (!ms || ms < 0) return "0s";
  const totalSec = Math.max(1, Math.round(ms / 1000));
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  if (h > 0) return `${h}h ${m}m ${s}s`;
  if (m > 0) return `${m}m ${s}s`;
  return `${s}s`;
};

const formatSize = (mb) => {
  if (mb === undefined || mb === null || isNaN(mb) || mb <= 0) return "0 MB";
  const abs = Math.abs(mb);
  if (abs >= 1024) return (abs / 1024).toFixed(2) + " GB";
  return abs.toFixed(1) + " MB";
};

const makeJobDir = (parent) => {
  return fs.mkdtempSync(path.join(parent, "tdarr-av1-"));
};

const parseHmsToSec = (str) => {
  if (!str || typeof str !== "string") return 0;
  const m = str.trim().match(/^(\d+):(\d{1,2}):(\d{1,2}(?:\.\d+)?)/);
  if (!m) return 0;
  return parseInt(m[1], 10) * 3600 + parseInt(m[2], 10) * 60 + parseFloat(m[3]);
};

const resolveProbeDuration = (p) => {
  if (!p) return null;
  let d = Number(p.format?.duration);
  if (d > 0 && Number.isFinite(d)) return d;
  const v = (p.streams || []).find(s => s.codec_type === "video" && !s.disposition?.attached_pic && !s.disposition?.timed_thumbnails);
  if (v) {
    const vd = Number(v.duration);
    if (vd > 0 && Number.isFinite(vd)) return vd;
    if (v.tags) {
      const k = Object.keys(v.tags).find(t => t.toUpperCase() === "DURATION" || t.toUpperCase().startsWith("DURATION-"));
      if (k) {
        const td = parseHmsToSec(v.tags[k]);
        if (td > 0) return td;
      }
    }
  }
  const a = (p.streams || []).find(s => s.codec_type === "audio");
  if (a) {
    const ad = Number(a.duration);
    if (ad > 0 && Number.isFinite(ad)) return ad;
    if (a.tags) {
      const k = Object.keys(a.tags).find(t => t.toUpperCase() === "DURATION" || t.toUpperCase().startsWith("DURATION-"));
      if (k) {
        const td = parseHmsToSec(a.tags[k]);
        if (td > 0) return td;
      }
    }
  }
  return null;
};

// Embedded in the custom function when building the flow.
const timelineSpawn = require('child_process').spawn;
const timelineReadline = require('readline');

function runTimelineProcess(bin, argv, onLine, onProgress, onDiagnostic, timeoutMs=12*60*60*1000, idleTimeoutMs=30*60*1000) {
  return new Promise((resolve, reject) => {
    let proc;
    try { proc = timelineSpawn(bin, argv, {stdio:['ignore','pipe','pipe'],detached:true}); }
    catch (e) { reject(e); return; }
    if (typeof trackReservationChild==='function') trackReservationChild(proc);
    let stderr = '',stderrHead='',stderrLength=0;
    const fullDiagnostic=()=>stderrLength>8192?`${stderrHead}
... diagnostics truncated ...
${stderr}`:stderr;
    let pendingDiagnostic='',completeDiagnostics='',firstInfrastructureDiagnostic='';
    let timeoutReason = '';
    let lineError=null;
    const terminate=()=>{ if (typeof terminateReservationChild==='function') terminateReservationChild(proc,'SIGKILL'); else proc.kill('SIGKILL'); };
    const timer = setTimeout(() => { timeoutReason = `maximum runtime ${Math.round(timeoutMs/60000)} minutes`; terminate(); }, timeoutMs);
    if (timer.unref) timer.unref();
    let idleTimer=null;
    const refreshIdleTimer=()=>{
      if (!(idleTimeoutMs>0)) return;
      if (idleTimer) clearTimeout(idleTimer);
      idleTimer=setTimeout(()=>{ timeoutReason=`no process output for ${Math.round(idleTimeoutMs/60000)} minutes`; terminate(); },idleTimeoutMs);
      if (idleTimer.unref) idleTimer.unref();
    };
    refreshIdleTimer();
    proc.stdout.on('data',refreshIdleTimer);
    proc.stderr.on('data', chunk => {
      const diagnosticChunk=chunk.toString();
      stderrLength+=diagnosticChunk.length;
      stderrHead=(stderrHead+diagnosticChunk).slice(0,4096);
      stderr = (stderr + diagnosticChunk).slice(-8192);
      if(!firstInfrastructureDiagnostic){
        const match=stderr.match(VERIFICATION_INFRASTRUCTURE_RE);
        if(match)firstInfrastructureDiagnostic=stderr.slice(Math.max(0,match.index-60),match.index+300);
      }
      refreshIdleTimer();
      if(typeof onDiagnostic==='function'&&!lineError){
        pendingDiagnostic=(pendingDiagnostic+chunk.toString()).slice(-8192);
        const newline=pendingDiagnostic.lastIndexOf('\n');
        if(newline>=0){
          completeDiagnostics=(completeDiagnostics+pendingDiagnostic.slice(0,newline+1)).slice(-8192);
          pendingDiagnostic=pendingDiagnostic.slice(newline+1);
          try { onDiagnostic(completeDiagnostics,true); }
          catch(err) { lineError=err; terminate(); }
        }
      }
    });
    const lines = timelineReadline.createInterface({input:proc.stdout, crlfDelay:Infinity});
    let progressRecord={};
    const sampleFps=createFpsSampler();
    lines.on('line', line => {
      if (onLine && !lineError) {
        try { onLine(line); }
        catch (err) { lineError=err; terminate(); return; }
      }
      const split=String(line).indexOf('=');
      if(split<0)return;
      const key=String(line).slice(0,split),value=String(line).slice(split+1).trim();
      if(key==='out_time_us'||key==='fps'||key==='frame')progressRecord[key]=value;
      if(key==='progress'&&typeof onProgress==='function'){
        const timeUs=Number(progressRecord.out_time_us);
        if(Number.isFinite(timeUs))try{onProgress(timeUs,sampleFps(progressRecord.frame,progressRecord.fps));}catch(_){}
        progressRecord={};
      }
    });
    proc.on('error', err => { clearTimeout(timer); if(idleTimer)clearTimeout(idleTimer); if (typeof untrackReservationChild==='function') untrackReservationChild(proc); err.processFailure={bin,status:null,signal:null,timedOut:false,diagnostic:fullDiagnostic()}; reject(err); });
    proc.on('close', (status, signal) => {
      clearTimeout(timer);
      if(idleTimer)clearTimeout(idleTimer);
      if (typeof untrackReservationChild==='function') untrackReservationChild(proc);
      const processReason = timeoutReason ? `timed out: ${timeoutReason}` : `failed (${status ?? signal})`;
      if (typeof onDiagnostic==='function') { try { onDiagnostic(fullDiagnostic()); } catch (_) {} }
      if(lineError) { reject(lineError); return; }
      if (status !== 0 || firstInfrastructureDiagnostic) {
        const text=fullDiagnostic().trim();
        const diagnostic=(text.length>800?`${text.slice(0,350)} ... ${text.slice(-430)}`:text)+(firstInfrastructureDiagnostic?`; tool/resource cause: ${firstInfrastructureDiagnostic}`:'');
        const error=new Error(`${bin} ${processReason}: ${diagnostic}`);
        error.processFailure={bin,status,signal,timedOut:!!timeoutReason,infrastructure:!!firstInfrastructureDiagnostic,diagnostic:fullDiagnostic()};
        reject(error);
      }
      else resolve(fullDiagnostic());
    });
  });
}

async function measureStreamTimeline(ffprobe, file, streamIndex, type, onProgress, durationHint, role='file') {
  let first=Infinity, last=-Infinity, count=0, packetCount=0, invalid=0, missingPtsCount=0, missingTimestampCount=0;
  let previousDts=null,outputDtsNonIncreasingCount=0,missingDtsCount=0;
  const missingPtsPackets=[],missingTimestampPackets=[];
  let missingPtsBitmap=Buffer.alloc(0),missingTimestampBitmap=Buffer.alloc(0);
  const markMissingPacket=(bitmap,ordinal)=>{
    const byteIndex=Math.floor(ordinal/8);
    if(byteIndex>=bitmap.length){
      const grown=Buffer.alloc(Math.max(byteIndex+1,bitmap.length?bitmap.length*2:1024));
      bitmap.copy(grown);
      bitmap=grown;
