  };
  let fileBytes=0,lastPosition=0,lastRatio=0,lastReported=-1,lastReportAt=0,hasPacketPosition=false;
  try { fileBytes=fs.statSync(file).size; } catch (_) {}
  const emitProgress=(packet)=>{
    if(typeof onProgress!=='function')return;
    const position=Number(packet.position),pts=Number(packet.pts);
    if(Number.isFinite(position)&&position>=0){lastPosition=Math.max(lastPosition,position);hasPacketPosition=true;}
    let ratio=fileBytes>0&&hasPacketPosition?lastPosition/fileBytes:(Number.isFinite(pts)&&durationHint>0?pts/durationHint:0);
    ratio=Math.max(lastRatio,Math.max(0,Math.min(1,Number.isFinite(ratio)?ratio:0)));
    lastRatio=ratio;
    const now=Date.now();
    if(ratio-lastReported>=0.002||now-lastReportAt>=1000||ratio>=1){lastReported=ratio;lastReportAt=now;try{onProgress(ratio);}catch(_){}}
  };
  await runTimelineProcess(ffprobe, ['-v','error','-select_streams',String(streamIndex),'-show_packets','-show_entries','packet=pts_time,dts_time,duration_time,pos','-of','compact=p=0:nk=0',file], line => {
    const ptsMatch=line.match(/(?:^|\|)pts_time=([^|]+)/), dtsMatch=line.match(/(?:^|\|)dts_time=([^|]+)/), durMatch=line.match(/(?:^|\|)duration_time=([^|]+)/), posMatch=line.match(/(?:^|\|)pos=([^|]+)/);
    if (!ptsMatch && !dtsMatch) return;
    const packetOrdinal=packetCount++;
    const pts=ptsMatch && ptsMatch[1] !== 'N/A' ? Number(ptsMatch[1]) : NaN;
    const dts=dtsMatch && dtsMatch[1] !== 'N/A' ? Number(dtsMatch[1]) : NaN;
    if (Number.isFinite(dts)) {
      if (previousDts!==null && dts<=previousDts) outputDtsNonIncreasingCount++;
      previousDts=dts;
    } else missingDtsCount++;
    if(!Number.isFinite(pts)){
      missingPtsCount++;
      if(missingPtsPackets.length<1024)missingPtsPackets.push(packetOrdinal);
      if(type==='audio')missingPtsBitmap=markMissingPacket(missingPtsBitmap,packetOrdinal);
    }
    if(!Number.isFinite(pts)&&!Number.isFinite(dts)){
      missingTimestampCount++;
      if(missingTimestampPackets.length<1024)missingTimestampPackets.push(packetOrdinal);
      if(type==='audio')missingTimestampBitmap=markMissingPacket(missingTimestampBitmap,packetOrdinal);
    }
    const duration=durMatch && durMatch[1] !== 'N/A' ? Number(durMatch[1]) : 0;
    emitProgress({pts:Number.isFinite(pts)?pts:dts,position:posMatch&&posMatch[1]!=='N/A'?Number(posMatch[1]):NaN});
    const timelineTime=type==='audio'&&!Number.isFinite(pts)?dts:pts;
    if (!Number.isFinite(timelineTime)) { invalid++; return; }
    first=Math.min(first,timelineTime);
    last=Math.max(last,timelineTime+(Number.isFinite(duration)&&duration>0?duration:0));
    count++;
  });
  if(typeof onProgress==='function')try{onProgress(1);}catch(_){}
  if (invalid && type!=='audio') {
    const firstMissing=(missingTimestampPackets[0] ?? missingPtsPackets[0]);
    const packetText=firstMissing===undefined?'':' (first at packet '+(firstMissing+1)+')';
    throw validationUnavailable(`${type} ${role} stream ${streamIndex} has ${invalid} packets without a usable ${type==='audio'?'PTS or DTS':'PTS'}${packetText}`);
  }
  if (count===0 && type==='subtitle') return {empty:true};
  if (count===0 && type==='audio' && packetCount>0) throw validationUnavailable(`audio ${role} stream ${streamIndex} has no packets with usable PTS or DTS`);
  if (count===0 || !Number.isFinite(first) || !Number.isFinite(last) || (type==='video' && (count<2 || !(last>first)))) throw validationUnavailable(`${type} ${role} stream ${streamIndex} timeline is unavailable or too short to verify`);
  const bitmapBytes=Math.ceil(packetCount/8);
  return {first,last,duration:last-first,packets:count,totalPackets:packetCount,outputDtsNonIncreasingCount,missingDtsCount,missingPtsCount,missingPtsPackets,missingPtsTruncated:missingPtsCount>missingPtsPackets.length,missingPtsBitmap:missingPtsBitmap.subarray(0,bitmapBytes),missingTimestampCount,missingTimestampPackets,missingTimestampsTruncated:missingTimestampCount>missingTimestampPackets.length,missingTimestampBitmap:missingTimestampBitmap.subarray(0,bitmapBytes),empty:false};
}

async function verifyVideoTimeline(ffprobe, ffmpeg, source, output, sourceIndex, outputIndex, tracks, updateWorker, durationHints, assertSourceStable, audioTimestampRepairIndices=[], validationReport=newValidationReport(), canUseQsv=true) {
  const pgsSubtitleCount=tracks.subtitle.filter(track=>track[2]==='hdmv_pgs_subtitle').length;
  const timelinePairCount=1+tracks.audio.length+(tracks.subtitle.length-pgsSubtitleCount)+(pgsSubtitleCount?1:0);
  let completedTimelinePairs=0,lastTimelinePercent=90;
  const scanTimelinePair=async operation=>{
    const pairIndex=completedTimelinePairs++;
    const reportPart=(part,ratio)=>{
      const progress=Math.max(0,Math.min(1,Number(ratio)||0));
      const fraction=(pairIndex+(part+progress)/2)/timelinePairCount;
      const percentage=Math.min(96,90+6*fraction);
      if(percentage>=lastTimelinePercent+0.05||fraction>=1){lastTimelinePercent=percentage;reportWorkerProgress(updateWorker,{percentage,fps:0,status:"Validation: packet timelines"});}
    };
    if(typeof assertSourceStable==='function')assertSourceStable();
    await operation(ratio=>reportPart(0,ratio),ratio=>reportPart(1,ratio));
    if(typeof assertSourceStable==='function')assertSourceStable();
    reportPart(1,1);
  };
  reportWorkerProgress(updateWorker,{percentage:90,fps:0,status:"Validation: packet timelines"});
  let a,b;
  await scanTimelinePair(async(sourceProgress,outputProgress)=>{
    a=await measureStreamTimeline(ffprobe,source,sourceIndex,'video',sourceProgress,durationHints?.source,'source');
    b=await measureStreamTimeline(ffprobe,output,outputIndex,'video',outputProgress,durationHints?.output,'candidate');
  });
  validateVideoPacketDts(a,b);
  if(typeof durationHints?.log==='function')durationHints.log(`[Video packets] Non-increasing DTS transitions: source ${a.outputDtsNonIncreasingCount}, candidate ${b.outputDtsNonIncreasingCount}; missing DTS: source ${a.missingDtsCount}, candidate ${b.missingDtsCount}.`);
  const tolerance=Math.max(0.5,a.duration*0.005);
  if (Math.abs(a.duration-b.duration)>tolerance) throw new Error(`Output video duration ${b.duration.toFixed(3)}s differs from source video ${a.duration.toFixed(3)}s (tolerance ${tolerance.toFixed(3)}s)`);
  const shift=b.first-a.first;
  const subtitleTimestampRepairs=[];
  const audioTimestampFindings=[];
  const pgsTracksToVerify=[];
  for (const type of ['audio','subtitle']) {
    for (const [srcIndex,dstIndex,sourceCodec,outputCodec] of tracks[type]) {
      if (type === 'subtitle' && sourceCodec === 'hdmv_pgs_subtitle') { pgsTracksToVerify.push([srcIndex,dstIndex]); continue; }
      if (type === 'subtitle' && ['ass','ssa'].includes(String(sourceCodec||'').toLowerCase()) && String(outputCodec||'').toLowerCase()===String(sourceCodec||'').toLowerCase()) {
        let sourcePackets,outputPackets;
        await scanTimelinePair(async(sourceProgress,outputProgress)=>{
          sourcePackets=await readSubtitlePackets(ffprobe,source,srcIndex,sourceProgress,durationHints?.source);
          outputPackets=await readSubtitlePackets(ffprobe,output,dstIndex,outputProgress,durationHints?.output);
        });
        const timingResult=validateCopiedSubtitlePackets(sourcePackets,outputPackets,shift);
        if (timingResult.adjustedPackets || timingResult.reorderedPackets) subtitleTimestampRepairs.push({sourceIndex:srcIndex,...timingResult});
        continue;
      }
      let s,d;
      await scanTimelinePair(async(sourceProgress,outputProgress)=>{
        s=await measureStreamTimeline(ffprobe,source,srcIndex,type,sourceProgress,durationHints?.source,'source');
        d=await measureStreamTimeline(ffprobe,output,dstIndex,type,outputProgress,durationHints?.output,'candidate');
      });
      if (s.empty && d.empty) continue;
      if (type==='audio' && audioTimestampRepairIndices.includes(srcIndex)) {
        if (s.totalPackets!==d.totalPackets) throw new Error(`Repaired audio packet count differs for stream ${srcIndex}: source ${s.totalPackets}, candidate ${d.totalPackets}`);
        if (d.outputDtsNonIncreasingCount!==0) throw new Error(`Repaired audio output DTS is still non-increasing for stream ${srcIndex} (${d.outputDtsNonIncreasingCount} packet transition(s))`);
        audioTimestampFindings.push({sourceIndex:srcIndex,message:`bounded timestamp repair passed: ${s.totalPackets} packets preserved; candidate DTS is strictly increasing`});
      }
      if (type==='audio' && (s.missingPtsCount || d.missingPtsCount || s.missingTimestampCount || d.missingTimestampCount)) {
        if ((d.missingPtsCount || d.missingTimestampCount) && s.totalPackets!==d.totalPackets) throw new Error(`Output audio stream ${srcIndex} has ${d.totalPackets} packets vs source ${s.totalPackets}; packet ordinals cannot safely establish whether missing timestamps were introduced`);
        const findIntroducedMissing=(candidateBitmap,sourceBitmap,packetCount)=>{
          let count=0,first=-1;
          const byteCount=Math.ceil(packetCount/8);
          for(let byteIndex=0;byteIndex<byteCount;byteIndex++){
            let introduced=(candidateBitmap[byteIndex]||0)&~(sourceBitmap[byteIndex]||0);
            if(!introduced)continue;
            if(first<0){for(let bit=0;bit<8;bit++)if(introduced&(1<<bit)){first=byteIndex*8+bit;break;}}
            while(introduced){introduced&=introduced-1;count++;}
          }
          return {count,first};
        };
        const introducedPts=findIntroducedMissing(d.missingPtsBitmap,s.missingPtsBitmap,d.totalPackets);
        const introducedTimestamps=findIntroducedMissing(d.missingTimestampBitmap,s.missingTimestampBitmap,d.totalPackets);
        if (introducedPts.count || introducedTimestamps.count) {
          const details=[];
          if(introducedPts.count)details.push(`${introducedPts.count} packet(s) missing PTS newly in candidate (first packet ${introducedPts.first+1})`);
          if(introducedTimestamps.count)details.push(`${introducedTimestamps.count} packet(s) missing both PTS and DTS newly in candidate (first packet ${introducedTimestamps.first+1})`);
          throw new Error(`Output audio stream ${srcIndex} worsened source timestamp coverage: ${details.join('; ')}; source had ${s.missingPtsCount} packet(s) without PTS and ${s.missingTimestampCount} without PTS or DTS`);
        }
        if(s.missingPtsCount && !d.missingPtsCount) audioTimestampFindings.push({sourceIndex:srcIndex,message:`source had ${s.missingPtsCount} packet(s) without PTS; candidate supplies PTS for all`});
        else if(d.missingPtsCount) audioTimestampFindings.push({sourceIndex:srcIndex,message:`preserved ${d.missingPtsCount} source packet(s) without PTS; DTS was used where available`});
        if(s.missingTimestampCount && !d.missingTimestampCount) audioTimestampFindings.push({sourceIndex:srcIndex,message:`candidate restored usable timestamps for ${s.missingTimestampCount} source packet(s)`});
        else if(d.missingTimestampCount) audioTimestampFindings.push({sourceIndex:srcIndex,message:`preserved ${d.missingTimestampCount} source packet(s) without either PTS or DTS`});
      }
      if (s.empty && d.empty) continue;
      if (type === 'subtitle' && !s.empty && !d.empty && d.packets < s.packets) throw new Error(`Output subtitle packet count ${d.packets} is less than source ${s.packets} for stream ${srcIndex}`);
      if (s.empty || d.empty || Math.abs((d.first-s.first)-shift)>0.1 || Math.abs((d.last-s.last)-shift)>0.1) throw new Error(`Output ${type} timeline differs from source for stream ${srcIndex}`);
    }
  }
  if(pgsTracksToVerify.length)await scanTimelinePair((sourceProgress,outputProgress)=>verifyPgsSegmentsBatch(ffmpeg,source,output,pgsTracksToVerify,shift,sourceProgress,outputProgress,durationHints?.source,durationHints?.output));
  const arcDevice=process.env.TDARR_ARC_DEVICE || '/dev/dri/renderD129';
  const decode=['-v','error','-xerror','-progress','pipe:1','-nostats','-init_hw_device',`vaapi=va:${arcDevice}`,'-init_hw_device','qsv=hw@va','-hwaccel','qsv','-hwaccel_device','hw','-hwaccel_output_format','qsv','-i',output,'-map',`0:${outputIndex}`];

  decode.push('-f','null','-');
  reportWorkerProgress(updateWorker,{percentage:96,fps:0,status:"Validation: strict output video decode"});
  await verifyCandidateDecodes({
    report:validationReport,canUseQsv,audioTracks:tracks.audio,sourceVideoIndex:sourceIndex,
    candidatePacketTimestampsVerified:durationHints?.strictCandidateFrames===true && a.totalPackets>0 && b.totalPackets>0 && b.missingDtsCount===0 && b.outputDtsNonIncreasingCount<=a.outputDtsNonIncreasingCount,
    isCorruption:type=>type==='video'?isKnownVideoCorruptionDiagnostic:isKnownAudioCorruptionDiagnostic,
    runVideo:async mode=>{
      const decodeStartedAt=Date.now();
      let decodeStatus='completed (exit 0)';
      try {
      if(mode==='timestamp-isolated'){
        reportWorkerProgress(updateWorker,{percentage:96,fps:0,status:"Validation: timestamp-isolated software decode"});
        return await verifyTimestampIsolatedVideo({ffmpeg,input:output,index:outputIndex,threads:getDecodeThreadCount(),expectedFrames:durationHints?.verifiedFrames,runProcess:runTimelineProcess});
      }
      const argv=mode==='qsv'?decode:withDecoderThreads(['-v','error','-xerror','-progress','pipe:1','-nostats','-i',output,'-map',`0:${outputIndex}`,'-f','null','-'],getDecodeThreadCount());
      const status=mode==='qsv'?"Validation: strict output video decode":"Validation: strict software video decode";
      reportWorkerProgress(updateWorker,{percentage:96,fps:0,status});
      return await runTimelineProcess(ffmpeg,argv,null,(timeUs,fps)=>{
        const ratio=a.duration>0?Math.min(1,Math.max(0,timeUs/1000000/a.duration)):0;
        const data={percentage:96+3*ratio,status};
        if(Number.isFinite(fps)&&fps>0)data.fps=fps;
        reportWorkerProgress(updateWorker,data);
      });
      } catch(error) {
        decodeStatus=`failed (exit ${error?.processFailure?.status ?? error?.processFailure?.signal ?? 'unknown'})`;
        throw error;
      } finally {
        if(typeof durationHints?.log==='function')durationHints.log(`[Validation decode] ${mode} ${decodeStatus} in ${((Date.now()-decodeStartedAt)/1000).toFixed(2)}s.`);
      }
    },
    runAudio:async indices=>{
      const audioDecode=withDecoderThreads(['-v','error','-xerror','-progress','pipe:1','-nostats','-i',output],getDecodeThreadCount());
      for (const dstIndex of indices) audioDecode.push('-map',`0:${dstIndex}`);
      audioDecode.push('-f','null','-');
      return await runTimelineProcess(ffmpeg,audioDecode,null,(timeUs,fps)=>{
        const duration=Number(durationHints?.output)||a.duration;
        const ratio=duration>0?Math.min(1,Math.max(0,timeUs/1000000/duration)):0;
        const data={percentage:99+0.9*ratio,status:"Validation: retained audio decode"};
        if(Number.isFinite(fps)&&fps>0)data.fps=fps;
        reportWorkerProgress(updateWorker,data);
      });
    },
    checkSource:async(type,index)=>{
      const args=withDecoderThreads(['-v','error','-xerror','-i',source,'-map',`0:${index}`,'-f','null','-'],getDecodeThreadCount());
      if(typeof assertSourceStable==='function')assertSourceStable();
      try {return await runTimelineProcess(ffmpeg,args);}
      finally {if(typeof assertSourceStable==='function')assertSourceStable();}
    }
  });
  return {sourceDuration:a.duration,outputDuration:b.duration,subtitleTimestampRepairs,audioTimestampFindings};
}

const validateOutput = async (ffprobeBin, sourcePath, outputPath, expected) => {
