  }
  if (expected.untagged) {
    validateUntaggedOutput(expected.sdrSource,video[0],outputFrameScan);
    if (outputFrameScan.interlaced || outputFrameScan.dovi || outputFrameScan.hdr10plus || outputFrameScan.otherDynamic || outputFrameScan.staticInfo.mastering || outputFrameScan.staticInfo.light || outputFrameScan.staticInfo.conflict) throw Error("Untagged output contains unexpected HDR metadata");
  }

  },"rejected");
  const {sourceVideo,tracks}=await validationStage(validationReport,"streams",async()=>{
  // 2. Audio & Subtitle stream count & codec checks
  for (const type of ["audio", "subtitle"]) {
    const actualStreams = (dst.streams || []).filter(s => s.codec_type === type);
    if (actualStreams.length !== expected[type]) {
      throw new Error(`Output ${type} count ${actualStreams.length} does not match expected ${expected[type]}`);
    }
    const expectedCodecs = expected[type + "Codecs"];
    if (expectedCodecs && expectedCodecs.length > 0) {
      actualStreams.forEach((s, i) => {
        const expCodec = expectedCodecs[i];
        if (expCodec && (s.codec_name || "").toLowerCase() !== expCodec.toLowerCase()) {
