    if(cachedPrecheck){
      frameScan=cachedPrecheck.frameScan;
      log(`[Source precheck] Reused ${frameScan.frames} verified source frames from quarantine.`);
    } else frameScan=await inspectVideoFrames(ffprobeBin,inputPath,mainVideo.index,scanOptions);
    assertOriginalUnchanged();
    if(preflightLevel6 && preflightLevel6.frames!==frameScan.frames) throw Error(`Dolby Level 6 frame count mismatch (${preflightLevel6.frames} / ${frameScan.frames})`);
    if (frameScan.interlaced) throw Error("Interlaced video frames are unsupported");
    if (frameScan.colorInfo.conflict) throw Error("Source frame color signaling conflicts with the stream");
    validateSdrFrameSignaling(preflightBasic,frameScan,mainVideo);
    log(`[Source precheck] Scanned ${frameScan.frames} frames in ${((Date.now()-sourceScanStartedAt)/1000).toFixed(2)}s.`);
  } catch (err) {
    const detail=String(err?.message || err);
    const sourceCorruption=isKnownVideoCorruptionDiagnostic(detail) || detail.toLowerCase().includes('[source media corruption]');
    const sourceDetail=detail.replace(/^(?:\[Source media corruption\]\s*)+/i,'');
    if (!args.variables) args.variables={}; if (!args.variables.user) args.variables.user={};
    const originalGuard=/^Original library file changed during processing/i.test(detail);
    args.variables.user.failure_reason=sourceCorruption ? `[Source media corruption] ${sourceDetail}` : originalGuard ? `[Original guard] ${detail}; original retained.` : `[Video guard] ${detail}; original retained.`;
    log(args.variables.user.failure_reason);
    return {outputFileObj:args.inputFileObj,outputNumber:2,variables:args.variables};
  }
  reportWorkerProgress(args.updateWorker,{percentage:8,fps:0,status:"Precheck: classify source color and HDR"},initialWorkerProgressDetails);
  let sourceScanFailureDetail="";
  const vCodec = (mainVideo.codec_name || "").toLowerCase();
  const width = parseInt(mainVideo.width || 0, 10) || 1920;
  const height = parseInt(mainVideo.height || 0, 10) || 1080;
  const rawPixFmt = (mainVideo.pix_fmt || "yuv420p").toLowerCase();
  const pixFmt = rawPixFmt.split("(")[0].trim();

  // 3. Color & HDR / DoVi Profile (Checking ffprobe color_transfer, color_trc, and side_data_list)
  const colorTransfer = (mainVideo.color_transfer || mainVideo.color_trc || "").toLowerCase();
  const colorSpace = (mainVideo.color_space || mainVideo.colorspace || "").toLowerCase();
  const colorPrimaries = (mainVideo.color_primaries || "").toLowerCase();
  const isHlg = colorTransfer === "arib-std-b67";
  const isPq = colorTransfer === "smpte2084";
  const isBt2020 = colorSpace === "bt2020nc" || colorSpace === "bt2020c" || colorPrimaries === "bt2020";
  const isDovi = Array.isArray(mainVideo.side_data_list) && mainVideo.side_data_list.some(sd =>
    String(sd.side_data_type || "").toLowerCase().includes("dovi") || sd.dv_profile !== undefined
  );
  const isHdr = isHlg || isPq || isDovi;

  // 4. Near-Lossless Lookahead ICQ Rate Control & Max AV1 Bitrate Calibration
  let quality = 19;
  let tierTargetKbps = 4500;
  let tierMaxKbps = 8000;
  let maxAv1Kbps = 8000;
  let resTierLabel = "1080p";
  const maxDim = Math.max(width, height);
  const minDim = Math.min(width, height);
  if (maxDim <= 1024 && minDim <= 576) {
    quality = 18;
    tierTargetKbps = 1200;
    tierMaxKbps = 2200;
    maxAv1Kbps = 2200;
    resTierLabel = "SD";
  } else if (maxDim <= 1280 && minDim <= 720) {
    quality = 19;
    tierTargetKbps = 2500;
    tierMaxKbps = 4500;
    maxAv1Kbps = 4500;
    resTierLabel = "720p";
  } else if (maxDim <= 1920 && minDim <= 1080) {
    quality = 19;
    tierTargetKbps = 4500;
    tierMaxKbps = 8000;
    maxAv1Kbps = 8000;
    resTierLabel = "1080p";
  } else if (isHdr) {
    quality = 18;
    tierTargetKbps = 18000;
    tierMaxKbps = 32000;
    maxAv1Kbps = 32000;
    resTierLabel = "4K UHD HDR";
  } else {
    quality = 19;
    tierTargetKbps = 12000;
    tierMaxKbps = 20000;
    maxAv1Kbps = 20000;
    resTierLabel = "4K UHD SDR";
  }

  // True Video/Container Duration Resolution & Oversized AV1 Detection
  const parseHmsToSec = (str) => {
    if (!str || typeof str !== "string") return 0;
    const m = str.trim().match(/^(\d+):(\d{1,2}):(\d{1,2}(?:\.\d+)?)/);
    if (!m) return 0;
    return parseInt(m[1], 10) * 3600 + parseInt(m[2], 10) * 60 + parseFloat(m[3]);
  };
  let videoDurationSec = parseFloat(mainVideo.duration || 0);
  if (!(videoDurationSec > 0) && mainVideo.tags) {
    const durTagKey = Object.keys(mainVideo.tags).find(k => k.toUpperCase() === "DURATION" || k.toUpperCase().startsWith("DURATION-"));
    if (durTagKey) {
      videoDurationSec = parseHmsToSec(mainVideo.tags[durTagKey]);
    }
  }
  if (!(videoDurationSec > 0) && Array.isArray(args.inputFileObj?.mediaInfo?.track)) {
    const miVid = args.inputFileObj.mediaInfo.track.find(t => (t["@type"] || "").toLowerCase() === "video");
    if (miVid && miVid.Duration) {
      videoDurationSec = parseFloat(miVid.Duration) || 0;
    }
  }
  const formatDurationSec = parseFloat(args.inputFileObj?.ffProbeData?.format?.duration || 0);
  const durationSec = (videoDurationSec > 1 && formatDurationSec > 1)
    ? Math.min(videoDurationSec, formatDurationSec)
    : (videoDurationSec > 1 ? videoDurationSec : formatDurationSec);

  const normalizeLang = (raw) => {
    const l = (raw || "und").toLowerCase().trim().split(/[-_]/)[0];
    if (["eng", "en"].includes(l)) return "eng";
    if (["jpn", "ja", "jp"].includes(l)) return "jpn";
    if (["zho", "chi", "zh", "cmn", "yue"].includes(l)) return "zho";
    if (["ita", "it"].includes(l)) return "ita";
    if (["spa", "es"].includes(l)) return "spa";
    return l || "und";
  };

  // Keep ambiguous audio and subtitle tracks; metadata alone does not prove duplication.

  const formatTags = args.inputFileObj?.ffProbeData?.format?.tags || {};
  const encodedByKey = Object.keys(formatTags).find(k => k.toLowerCase() === "encoded_by");
  const isEncodedByUs = false;
  let hdrClass, hdrSource, sdrSource, hdrLightOverride = null, hdrMasterOverride = null;
  delete args.variables.user.hdr_conversion;
  try {
    const infoVideos = [preflightInfoVideo];
    const basic = preflightBasic;
    if (isVerifiedSdr(basic,frameScan)) {
      validateEffectiveSdrTransfer(mainVideo,infoVideos[0],frameScan);
      sdrSource = effectiveSdrSource(mainVideo,infoVideos[0],frameScan);
      hdrClass = "sdr";
      const unspecifiedSdrFields=["color_transfer","color_primaries"].filter(field=>isUnknownColorValue(sdrSource[field]));
      if (unspecifiedSdrFields.length && normalizeSdrMatrix(mainVideo.color_space)) log(`[Color] Recognized SDR ${normalizeSdrMatrix(mainVideo.color_space)} matrix; ${unspecifiedSdrFields.join(" and ")} remain unspecified.`);
    } else if (isUntaggedVideo(mainVideo,infoVideos[0],frameScan)) {
      hdrClass = "untagged";
      sdrSource = {...mainVideo};
      const effectiveRange=inferUntaggedColorRange(mainVideo,infoVideos[0],frameScan);
      if (!effectiveRange) throw new Error("Untagged SDR YUV range could not be inferred safely");
      sdrSource.color_range=effectiveRange;
      log(`[Color] Input transfer, primaries, and matrix are unspecified; using ${effectiveRange==='tv'?'TV limited':'PC full'} range for the untagged SDR YUV encode.`);
    } else {
      hdrClass = determineHdrRoute(mainVideo,infoVideos[0],frameScan);
      if (hdrClass === "hlg") {
        if (frameScan.staticInfo.mastering || frameScan.staticInfo.light || frameScan.staticInfo.conflict) throw Error("HLG source has additional static HDR metadata that is not verified");
        hdrSource = mainVideo;
        validateHlg(hdrSource,hdrSource);
      } else if (hdrClass === "dovi5_hdr10") {
        if (preflightDoviRoute==="dovi5_hdr10" && preflightHdrSource) {
          hdrSource=preflightHdrSource;
          hdrMasterOverride=preflightHdrMasterOverride;
          hdrLightOverride=preflightHdrLightOverride;
        } else {
          const dovi5Meta=await extractDolbyProfile5HdrMetadata(ffmpegBin,inputPath,mainVideo.index,frameScan.frames);
          const dovi5Target=buildDovi5HdrTarget(dovi5Meta.level6,dovi5Meta.level9);
          hdrSource=dovi5Target.targetVideo;
          hdrMasterOverride=dovi5Target.masteringDisplayArg;
          hdrLightOverride=dovi5Target.contentLightArg;
        }
      } else {
        const canUseDolbyLevel6 = hdrClass === "dovi81_hdr10" || hdrClass === "dovi7_hdr10" || hdrClass === "dovi81_hdr10plus_hdr10" || hdrClass === "dovi7_hdr10plus_hdr10";
        const doviProfile=route=>/^dovi(7|81)_hdr10(?:plus_hdr10)?$/.exec(String(route || ''))?.[1] || '';
        if(doviProfile(preflightDoviRoute) && doviProfile(preflightDoviRoute)===doviProfile(hdrClass) && preflightHdrSource) {
          hdrSource=preflightHdrSource;
          hdrLightOverride=preflightHdrLightOverride;
        } else {
          const mediaInfoHdrSeed=hdrClass==="hdr10"?seedHdrMetadataFromMediaInfo(mainVideo,infoVideos[0]):{video:mainVideo,added:[],contentLightOverride:null};
          if(mediaInfoHdrSeed.added.length)log(`[HDR metadata] Filled missing FFprobe side data from stream-sourced MediaInfo fields: ${mediaInfoHdrSeed.added.join(", ")}. Candidate metadata must still match these values.`);
          hdrSource = mergeHdrMetadata(mediaInfoHdrSeed.video,readHdrFrames(ffprobeBin,inputPath,mainVideo.index),{allowMissingLight:canUseDolbyLevel6,allowMissingAll:hdrClass==="hdr10"});
          const resolved = await resolveHdrLight(hdrSource,hdrClass,() => extractDolbyLevel6(ffmpegBin,inputPath,mainVideo.index,frameScan.frames));
          if (resolved.warning) log(`[HDR warning] ${resolved.warning}`);
          hdrSource = resolved.metadata; hdrLightOverride = resolved.override || mediaInfoHdrSeed.contentLightOverride;
        }
        checkHdrFrameStatic(hdrSource,frameScan,!canUseDolbyLevel6 && hdrClass!=="hdr10",hdrClass!=="hdr10");
      }
      if (hdrClass === "hdr10plus_hdr10") {
        args.variables.user.hdr_conversion = "HDR10+ to HDR10 base layer; HDR10+ dynamic metadata removed";
        log(`[HDR] ${args.variables.user.hdr_conversion}`);
      }
      if (hdrClass === "dovi81_hdr10plus_hdr10") {
        args.variables.user.hdr_conversion = "Hybrid Dolby Vision 8.1 and HDR10+ to verified HDR10; both dynamic metadata formats removed";
        log(`[HDR] ${args.variables.user.hdr_conversion}`);
      }
      if (hdrClass === "dovi7_hdr10plus_hdr10") {
        args.variables.user.hdr_conversion = "Hybrid Dolby Vision Profile 7 and HDR10+ to verified HDR10 base layer; Dolby Vision and HDR10+ dynamic metadata removed";
        log(`[HDR] ${args.variables.user.hdr_conversion}`);
      }
      if (hdrClass === "dovi81_hdr10") {
        args.variables.user.hdr_conversion = "Dolby Vision 8.1 to HDR10 base layer; Dolby Vision dynamic metadata removed";
        log(`[HDR] ${args.variables.user.hdr_conversion}`);
      }
      if (hdrClass === "dovi7_hdr10") {
        args.variables.user.hdr_conversion = "Dolby Vision Profile 7 to HDR10 base layer; Dolby Vision enhancement layer and dynamic metadata removed";
        log(`[HDR] ${args.variables.user.hdr_conversion}`);
      }
      if (hdrClass === "dovi5_hdr10") {
        args.variables.user.hdr_conversion = "Dolby Vision Profile 5 to verified HDR10 (libplacebo IPT-PQ->BT.2020 PQ; Dolby Vision dynamic metadata removed)";
        log(`[HDR] ${args.variables.user.hdr_conversion}`);
      }
    }
  } catch (err) {
    log(`[HDR guard] ${err.message || err}; original retained.`);
    return {outputFileObj:args.inputFileObj,outputNumber:2,variables:args.variables};
  }

  let estVideoBitrateKbps = 0;
  if (durationSec > 0 && rawSizeMB > 0) {
    const totalBitrateKbps = (rawSizeMB * 1024 * 1024 * 8) / (durationSec * 1000);
    let nonVideoKbps = 0;
    streams.forEach(s => {
      if (s.codec_type === "audio") {
        const explicitKbps = Math.round(parseInt(s.bit_rate || s.tags?.BPS || 0, 10) / 1000);
        if (explicitKbps > 0 && explicitKbps < 15000) {
          nonVideoKbps += explicitKbps;
        } else {
          const ch = parseInt(s.channels || 2, 10);
          const c = (s.codec_name || "").toLowerCase();
          const prof = (s.profile || "").toLowerCase();
          const isLossless = prof.includes("dts-hd") || c.startsWith("pcm_") || ["truehd", "flac", "alac", "mlp"].some(m => c.includes(m));
          nonVideoKbps += isLossless ? (ch > 2 ? 3000 : 1000) : (ch > 2 ? 640 : 192);
        }
      } else if (s.codec_type === "subtitle") {
        const sc = (s.codec_name || "").toLowerCase();
        if (sc.includes("pgs") || sc.includes("dvd")) nonVideoKbps += 50;
      }
    });
    estVideoBitrateKbps = Math.max(0, Math.round(totalBitrateKbps - nonVideoKbps));
  } else if (parseInt(mainVideo.bit_rate || 0, 10) > 0) {
    estVideoBitrateKbps = Math.round(parseInt(mainVideo.bit_rate, 10) / 1000);
  }

  // Every eligible source, including AV1 produced by older flows, is re-encoded.
  const isOversizedAV1 = false;
  const isAlreadyAV1 = false;
  quality = selectedQuality;

  // 10-bit & Hardware Compatibility Detection
  const is10Bit = pixFmt.includes("10") || mainVideo.bits_per_raw_sample === "10" || mainVideo.bits_per_raw_sample === 10;
  const isH26410bit = (vCodec === "h264" && is10Bit); // Intel Arc lacks H.264 Hi10P hardware decoder
  const isVC1 = (vCodec === "vc1" || vCodec === "wmv3"); // Intel Arc lacks VC-1 hardware decoder
  const isNon420Chroma = pixFmt.includes("444") || pixFmt.includes("422");
  const needsProactiveHybrid = hdrClass === "dovi5_hdr10" || !useQsvDecode(mainVideo);
  const qsvHdrClampRetryEligible = isHdr && isQsvHdrMasteringClampRisk(hdrSource);
  let softwareHdrFallback = quarantinedCandidate?.kind === "svt_av1_encode" || (!quarantinedCandidate && qsvHdrClampRetryEligible);
  quality = softwareHdrFallback ? 28 : selectedQuality;
  let qualityLabel = softwareHdrFallback ? "SVT-AV1 CRF" : "ICQ";

  const encoderSupportedPixFmts = [
    "nv12", "p010", "p010le", "yuv420p", "yuv420p8", "yuv420p9le",
    "yuv420p10le", "yuv420p12le", "yuv420p16le"
  ];
  const isEncoderCompatible = isAlreadyAV1 || encoderSupportedPixFmts.includes(pixFmt) || isNon420Chroma;

  if (!isEncoderCompatible) {
    log(`[Arc AV1 Single-Pass] Incompatible pixel format (${pixFmt}) for QSV hardware encode.`);
    const totalDurationStr = formatDuration(Date.now() - startEpoch);
    const incompPayload = {
      embeds: [{
        title: `⚠️ ${titleName}`,
        description: [
          `📁 **Size:** \`${formatSize(rawSizeMB)}\``,
          `⚠️ **Reason:** Unsupported pixel format (${pixFmt}) or codec (${vCodec}) for hardware QSV`,
          `⏱️ **Duration:** ${totalDurationStr}`
        ].join("\n"),
        color: 16776960,
        footer: { text: "Tdarr AV1 Flow • QSV Compatibility Filter" },
        timestamp: new Date().toISOString()
      }]
    };
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  if (!isAlreadyAV1) {
    try {
      fs.accessSync(gpuDevice, fs.constants.R_OK | fs.constants.W_OK);
    } catch (err) {
      log(`[Arc GPU] Device not accessible: ${gpuDevice}: ${err.message || err}`);
      return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
    }
  }

  let pipelineMode = "";
  if (isAlreadyAV1) {
    pipelineMode = "Library Reprocessing: Subtitle Normalization & Seek Healing";
  } else if (isNon420Chroma) {
    pipelineMode = `Hybrid (${pixFmt} -> 4:2:0 Downsample + Arc QSV AV1 Encode)`;
  } else if (needsProactiveHybrid) {
    pipelineMode = `Hybrid (CPU Decode [${vCodec}${is10Bit ? " 10-bit" : ""}] + Arc QSV AV1 Encode)`;
  } else if (is10Bit) {
    pipelineMode = "Full QSV Hardware (Native 10-bit GPU Decode + Pass-Through VPP + GPU AV1 Encode)";
  } else {
    pipelineMode = "Full QSV Hardware (8-bit to 10-bit VPP + GPU AV1 Encode)";
  }
  if (!isAlreadyAV1 && isHdr) {
    pipelineMode += isHlg ? " [HLG]" : " [HDR10]";
  }
  if (quarantinedCandidate?.kind === "svt_av1_encode") {
    pipelineMode = "Software SVT-AV1 HDR candidate revalidation";
    log(`[Arc AV1] Revalidating a quarantined SVT-AV1 HDR candidate against the current checks.`);
  } else if (softwareHdrFallback) {
    pipelineMode = "Software SVT-AV1 HDR encode (proactive QSV green-y clamp avoidance)";
    log(`[Arc AV1] Source mastering display green-y coordinate exceeds the Intel QSV AV1 clamp limit; routing proactively to SVT-AV1 CRF 28 to preserve HDR metadata.`);
  }

  // 5. Audio Filtering & Language Priority (eng, jpn, zho, chi, ita, spa, und)
  const allowedAudioLangs = ["eng", "jpn", "zho", "ita", "spa", "und"];
  const badAudioCodecs = ["apple_apac", "apac"];
  const rawAudioStreams = streams.filter(s => {
    if (s.codec_type !== "audio") return false;
    const c = (s.codec_name || "").toLowerCase();
    const cid = (s.codec_tag_string || s.codec_id || "").toLowerCase();
    return !badAudioCodecs.includes(c) && !badAudioCodecs.includes(cid) && c !== "none";
  });

  let candidateAudio = rawAudioStreams.filter(s => {
    const lang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
    return allowedAudioLangs.includes(lang);
  });
  if (candidateAudio.length === 0) candidateAudio = rawAudioStreams;

  // Conditional Priority: If Japanese audio is present, prune Chinese audio tracks
  const hasJapanese = candidateAudio.some(s => normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "") === "jpn");
  if (hasJapanese) {
    const nonZho = candidateAudio.filter(s => {
      const rawLang = (s.tags?.language || s.tags?.LANGUAGE || "").toLowerCase();
      if (normalizeLang(rawLang) === "zho") {
        console.log(`[Audio Filter] Japanese present; pruning Chinese stream 0:${s.index} (${rawLang})`);
        return false;
      }
      return true;
    });
    if (nonZho.length > 0) candidateAudio = nonZho;
  }

  // Redundant Legacy Core & Downmix Pruning per canonical language
  const prunedAudioIndices = new Set();
  const langAudioMap = {};
  candidateAudio.forEach(s => {
    const lang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
    if (!langAudioMap[lang]) langAudioMap[lang] = [];
    langAudioMap[lang].push(s);
  });

  Object.keys(langAudioMap).forEach(lang => {
    const tracks = langAudioMap[lang];
    const masterTrack = tracks.find(s => {
      const c = (s.codec_name || "").toLowerCase();
      const prof = (s.profile || "").toLowerCase();
      const ch = parseInt(s.channels || 0, 10);
      return (ch >= 6) && (ch > 6 || prof.includes("dts-hd") || c.startsWith("pcm_") || ["truehd", "dts-hd ma", "flac", "alac"].some(m => c.includes(m)));
    });
    const hasSurround = tracks.some(s => parseInt(s.channels || 0, 10) > 2);

    tracks.forEach(s => {
      const c = (s.codec_name || "").toLowerCase();
      const prof = (s.profile || "").toLowerCase();
      const ch = parseInt(s.channels || 0, 10);
      const title = (s.tags?.title || s.tags?.TITLE || "").toLowerCase();
      const isCommentary = s.disposition?.comment === 1 || title.includes("commentary") || title.includes("description");
      const isLossyCore = (c === "ac3") || (c === "dts" && !prof.includes("dts-hd"));

      // Omit redundant legacy core (e.g. AC3/DTS 5.1 alongside TrueHD/DTS-HD MA/FLAC/PCM master)
      if (masterTrack && s.index !== masterTrack.index && ch === 6 && isLossyCore && !isCommentary) {
        prunedAudioIndices.add(s.index);
        console.log(`[Audio Pruner] Omitted duplicate legacy core stream 0:${s.index} (${c} ${ch}ch) in favor of master stream 0:${masterTrack.index}`);
      }
      // Omit redundant AAC stereo downmix if surround exists
      if (hasSurround && tracks.length > 1 && ch <= 2 && c === "aac" && !isCommentary) {
        prunedAudioIndices.add(s.index);
        console.log(`[Audio Pruner] Omitted redundant AAC stereo downmix stream 0:${s.index} for language '${lang}'`);
      }
    });
  });

  const finalAudioStreams = candidateAudio.filter(s => !prunedAudioIndices.has(s.index));
  const audioTimestampRepairs = new Map();
  const currentAudioPrecheckStreams=finalAudioStreams.map(s=>({index:s.index,timeBase:String(s.time_base || '')}));
  const persistPrechecks=entry=>{
    if(!precheckSignature || !entry)return;
    assertOriginalUnchanged();
    const saved=savePrecheckCache(entry,precheckSignature,{frameScan,audio:{streams:currentAudioPrecheckStreams,repairs:Array.from(audioTimestampRepairs.entries())}});
    assertOriginalUnchanged();
    log(saved?'[Precheck cache] Saved full source video and retained-audio evidence.':'[Precheck cache] Evidence could not be cached; future retries will run source prechecks.');
  };

  // Full-decode the audio tracks that will actually be kept, before reserving scratch or encoding video.
  const precheckRetainedSourceAudio = async () => {
    if(cachedPrecheck && JSON.stringify(cachedPrecheck.audio.streams)===JSON.stringify(currentAudioPrecheckStreams)){
      for(const [index,timing] of cachedPrecheck.audio.repairs) audioTimestampRepairs.set(index,timing);
      log(`[Audio precheck] Reused verified timing and decode results for ${currentAudioPrecheckStreams.length} retained source track(s).`);
      return;
    }
    if (finalAudioStreams.length === 0) {
      log("[Audio precheck] No retained audio tracks; source audio decode skipped.");
      reportWorkerProgress(args.updateWorker,{percentage:10,fps:0,status:"Precheck: no retained audio tracks"},initialWorkerProgressDetails);
      return;
    }
    log(`[Audio precheck] Full software decode of ${finalAudioStreams.length} retained source audio track(s) before the Arc encode.`);
    const decodeAudioStreams=async (streams,startPercent,endPercent) => {
      const decodeArgs=withDecoderThreads(["-v","error","-xerror","-progress","pipe:1","-nostats","-i",inputPath],getDecodeThreadCount());
      for (const stream of streams) decodeArgs.push("-map",`0:${stream.index}`);
      decodeArgs.push("-f","null","-");
      reportWorkerProgress(args.updateWorker,{percentage:startPercent,fps:0,status:"Precheck: retained audio decode"},initialWorkerProgressDetails);
      const stderr=await runTimelineProcess(ffmpegBin,decodeArgs,null,(timeUs)=>{
        const decodedSec=Number(timeUs)/1000000;
        const ratio=durationSec>0 && Number.isFinite(decodedSec)?Math.min(1,Math.max(0,decodedSec/durationSec)):0;
        reportWorkerProgress(args.updateWorker,{percentage:startPercent+(endPercent-startPercent)*ratio,fps:0,status:"Precheck: retained audio decode"},initialWorkerProgressDetails);
      });
      if(isVerificationInfrastructureDiagnostic(stderr))throw Error(String(stderr).trim());
      return String(stderr || "").trim();
    };
    const logTrackPassed=(stream,diagnostic)=>{
      if (diagnostic) log(`[Audio precheck] Non-fatal FFmpeg diagnostic on source stream 0:${stream.index}: ${diagnostic.slice(-400)}`);
      const language=normalizeLang(stream.tags?.language || stream.tags?.LANGUAGE || "und");
      log(`[Audio precheck] Audio source stream 0:${stream.index} (${language}) passed full decode.`);
    };
    for (let position=0; position<finalAudioStreams.length; position++) {
      const stream=finalAudioStreams[position];
      const percentStart=8+position/finalAudioStreams.length;
      const percentEnd=8+(position+1)/finalAudioStreams.length;
      let lastAudioProgress=percentStart-1;
      log(`[Audio precheck] Scanning DTS order for retained source stream 0:${stream.index}.`);
      reportWorkerProgress(args.updateWorker,{percentage:percentStart,fps:0,status:"Precheck: audio DTS scan"},initialWorkerProgressDetails);
      const timing=await scanAudioDtsPackets(ffprobeBin,inputPath,stream.index,stream.time_base,runTimelineProcess,ratio=>{
        const percentage=percentStart+(percentEnd-percentStart)*Math.max(0,Math.min(1,Number(ratio)||0));
        if(percentage>=lastAudioProgress+0.02||percentage>=percentEnd){lastAudioProgress=percentage;reportWorkerProgress(args.updateWorker,{percentage,fps:0,status:"Precheck: audio DTS scan"},initialWorkerProgressDetails);}
      },originalSourceSizeInBytes);
      if (timing.backwardSteps===0) {
        if (timing.nonIncreasingSteps>0) log(`[Audio precheck] Source audio stream 0:${stream.index} has ${timing.nonIncreasingSteps} equal DTS transition(s) at time base ${stream.time_base}; these are preserved without repair.`);
        continue;
      }
      if (!timing.repairable) {
        const cause=timing.timeBaseKnown?`${timing.missingDts} packet(s) without DTS`:`no valid stream time base (${stream.time_base || "missing"})`;
        throw new Error(`[Audio guard] Source audio stream 0:${stream.index} has ${timing.backwardSteps} backward DTS transition(s), but ${cause}; a bounded copy repair cannot be proven safe.`);
      }
      if (!timing.withinLimit) throw new Error(`[Audio guard] Source audio stream 0:${stream.index} needs up to ${(timing.maxRepairSeconds*1000).toFixed(1)} ms of DTS correction, above the ${MAX_AUDIO_TIMESTAMP_REPAIR_SECONDS*1000} ms repair limit.`);
      audioTimestampRepairs.set(stream.index,timing);
      log(`[Audio precheck] Source audio timestamp repair: stream 0:${stream.index}; ${timing.backwardSteps} backward DTS transition(s), ${timing.nonIncreasingSteps-timing.backwardSteps} equal transition(s) preserved, ${timing.adjustedPackets} packet(s) adjusted, maximum ${(timing.maxRepairSeconds*1000).toFixed(1)} ms (limit ${MAX_AUDIO_TIMESTAMP_REPAIR_SECONDS*1000} ms); compressed audio remains stream-copied.`);
    }
    try {
      const diagnostic=await decodeAudioStreams(finalAudioStreams,9,10);
      if (isKnownAudioCorruptionDiagnostic(diagnostic)) throw new Error(diagnostic);
      for (const stream of finalAudioStreams) logTrackPassed(stream,diagnostic);
    } catch (batchError) {
      const batchDetail=String(batchError?.message || batchError).replace(/\s+/g," ").slice(-700);
      log("[Audio precheck] Combined decode failed; isolating retained tracks to identify the cause.");
      for (let position=0; position<finalAudioStreams.length; position++) {
        const stream=finalAudioStreams[position];
        const language=normalizeLang(stream.tags?.language || stream.tags?.LANGUAGE || "und");
        try {
          const diagnostic=await decodeAudioStreams([stream],9+position/finalAudioStreams.length,9+(position+1)/finalAudioStreams.length);
          if (isKnownAudioCorruptionDiagnostic(diagnostic)) throw new Error(diagnostic);
          logTrackPassed(stream,diagnostic);
        } catch (decodeError) {
          const detail=String(decodeError?.message || decodeError).replace(/\s+/g," ").slice(-700);
          const recognized=isKnownAudioCorruptionDiagnostic(detail);
          const prefix=recognized?"[Source media corruption]":"[Audio guard]";
          throw new Error(`${prefix} Audio source stream 0:${stream.index} (${language}) failed its full source decode precheck: ${detail}`);
        }
      }
      throw new Error(`[Audio guard] Combined retained audio decode failed, although each stream passed separately: ${batchDetail}`);
    }
    reportWorkerProgress(args.updateWorker,{percentage:10,fps:0,status:"Precheck: retained audio decode complete"},initialWorkerProgressDetails);
  };

  // 6. Subtitle Filtering & Safe Format Normalization (eng, ita, spa, und)
  const allowedSubLangs = ["eng", "ita", "spa", "und"];
  const toSrtCodecs = ["ass", "ssa", "eia_608", "c608", "cea-608", "cea-708", "mov_text", "tx3g", "webvtt", "vtt"];
  const toSrtCodecIDs = ["mov_text", "tx3g", "c608", "eia_608"];
  const inputContainer = String(args.inputFileObj?.container || path.extname(inputPath).slice(1)).toLowerCase();
  const isMatroskaContainer = ["mkv", "mka", "mks", "matroska"].includes(inputContainer);
  const shouldConvertSubToSrt = stream => {
    const codec = String(stream.codec_name || "").toLowerCase();
    const codecId = String(stream.codec_tag_string || stream.codec_id || "").toLowerCase();
    if (isMatroskaContainer && ["ass", "ssa"].includes(codec)) return false;
    return toSrtCodecs.includes(codec) || toSrtCodecIDs.includes(codecId);
  };

  const finalSubStreams = streams.filter(s => {
    if (s.codec_type !== "subtitle") return false;
    const c = (s.codec_name || "").toLowerCase();
    const cid = (s.codec_tag_string || s.codec_id || "").toLowerCase();
    // Drop corrupt 'none' or unmuxable s_text/webvtt tracks
    if (!c || c === "none" || cid === "s_text/webvtt") {
      console.log(`[Subtitle Filter] Dropping un-muxable subtitle stream 0:${s.index} (codec: ${c || cid || "none"})`);
      return false;
    }
    const lang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
    return allowedSubLangs.includes(lang);
  });

  // Styled Matroska subtitles can depend on attached fonts. Keep every
  // attachment when a retained ASS/SSA track is stream-copied.
  const retainAttachments=finalSubStreams.some(s=>['ass','ssa'].includes(String(s.codec_name || '').toLowerCase()) && !shouldConvertSubToSrt(s));
  const retainedAttachmentStreams=retainAttachments?streams.filter(s=>s.codec_type==='attachment'):[];
  if(retainedAttachmentStreams.length)log(`[Subtitle attachments] Retaining ${retainedAttachmentStreams.length} source attachment(s) for styled subtitles.`);
  const normalizedAssContents=new Map();
  const normalizedAssPaths=new Map();
  const normalizedAssInputIndex=new Map();
  if(retainAttachments && quarantinedCandidate && retainedAttachmentStreams.length){
    try {
      const candProbe=JSON.parse(execFileSync(ffprobeBin,["-v","error","-show_streams","-of","json",quarantinedCandidate.candidatePath],{encoding:"utf8",timeout:60000,maxBuffer:16*1024*1024}));
      const candAttachments=(candProbe.streams || []).filter(s=>s.codec_type==="attachment");
      if(candAttachments.length!==retainedAttachmentStreams.length){
        await removeQuarantineCandidate(quarantinedCandidate);
        log(`[Quarantine] Retired stored candidate missing required subtitle attachments (${candAttachments.length} vs ${retainedAttachmentStreams.length}); proceeding with fresh encode.`);
        quarantinedCandidate=null;
        delete args.variables.user.quarantine_entry;
      }
    } catch(_){}
  }
  if(retainAttachments){
    const guards=new Map(finalSubStreams.filter(s=>['ass','ssa'].includes(String(s.codec_name || '').toLowerCase()) && !shouldConvertSubToSrt(s)).map(s=>[s.index,createSubtitleTimingPrecheck()]));
    const subtitleStartedAt=Date.now();
    try {
      assertOriginalUnchanged();
      const diagnostic=await runTimelineProcess(ffprobeBin,['-v','error','-select_streams','s','-show_packets','-show_entries','packet=stream_index,pts_time,dts_time','-of','compact=p=0:nk=0',inputPath],line=>{
        const match=String(line).match(/(?:^|\|)stream_index=(\d+)/);
        if(!match)return;
        const index=Number(match[1]),guard=guards.get(index),packet=parseSubtitlePacketLine(line);
        if(!guard || !packet)return;
        guard.push(packet);
      });
      assertOriginalUnchanged();
      if(String(diagnostic || '').trim())throw Error(`Subtitle packet scan emitted diagnostics: ${String(diagnostic).trim().slice(-500)}`);
      for(const [index,guard] of guards){
        const result=guard.finish();
        if(result.missingPts)throw Error(`[Subtitle guard] ASS/SSA source stream 0:${index} has ${result.missingPts} packet(s) without a usable PTS`);
        if(result.firstOverLimitPacket!==null){
          let normAssText=null;
          try {
            assertOriginalUnchanged();
            const rawSubProbe=execFileSync(ffprobeBin,["-v","error","-select_streams",String(index),"-show_streams","-show_packets","-show_data","-show_data_hash","sha256","-of","json",inputPath],{encoding:"utf8",timeout:120000,maxBuffer:64*1024*1024});
            const parsedSubProbe=JSON.parse(rawSubProbe);
            if(Array.isArray(parsedSubProbe.packets) && parsedSubProbe.packets.length===result.packetCount
                && /^SHA256:[0-9a-f]{64}$/i.test(String(parsedSubProbe.streams?.[0]?.extradata_hash || ''))
                && parsedSubProbe.packets.every(packet=>/^SHA256:[0-9a-f]{64}$/i.test(String(packet.data_hash || '')))){
              normAssText=reconstructAssSubtitleFile(parsedSubProbe);
            }
          } catch(_){}
          if(!normAssText){
            throw Error(`[Subtitle guard] ASS/SSA source stream 0:${index} requires ${result.maxAdjustmentSeconds.toFixed(3)}s timestamp repair at packet ${result.firstOverLimitPacket+1} (limit 0.500s)`);
          }
          normalizedAssContents.set(index,normAssText);
          log(`[Subtitle precheck] ASS/SSA stream 0:${index} has out-of-order cues (up to ${result.maxAdjustmentSeconds.toFixed(3)}s backward step at packet ${result.firstOverLimitPacket+1}); reconstructed chronological ASS script for muxing.`);
        }
      }
      if(normalizedAssContents.size && quarantinedCandidate){
        let candidateSubNormalized=false;
        try {
          const candSubGuards=new Map();
          await runTimelineProcess(ffprobeBin,['-v','error','-select_streams','s','-show_packets','-show_entries','packet=stream_index,pts_time,dts_time','-of','compact=p=0:nk=0',quarantinedCandidate.candidatePath],line=>{
            const match=String(line).match(/(?:^|\|)stream_index=(\d+)/);
            if(!match)return;
            const idx=Number(match[1]),packet=parseSubtitlePacketLine(line);
            if(!packet)return;
            let g=candSubGuards.get(idx);
            if(!g){g=createSubtitleTimingPrecheck(0);candSubGuards.set(idx,g);}
            g.push(packet);
          });
          candidateSubNormalized=candSubGuards.size>0 && [...candSubGuards.values()].every(g=>g.finish().firstOverLimitPacket===null);
        } catch(_){}
        if(!candidateSubNormalized){
          try {
            await removeQuarantineCandidate(quarantinedCandidate);
            log(`[Quarantine] Retired stored candidate to apply chronological ASS/SSA subtitle normalization; proceeding with fresh encode.`);
          } catch(_){}
          quarantinedCandidate=null;
          delete args.variables.user.quarantine_entry;
        }
      }
      log(`[Subtitle precheck] Checked ${guards.size} ASS/SSA track(s) in ${((Date.now()-subtitleStartedAt)/1000).toFixed(2)}s.`);
    } catch(error) {
      const detail=String(error?.message || error);
      const reason=detail.startsWith('[Subtitle guard]')?detail:`[Subtitle guard] Could not verify source subtitle packet timing: ${detail}`;
      args.variables.user.failure_reason=`${reason}; original retained.`;
      log(args.variables.user.failure_reason);
      return {outputFileObj:args.inputFileObj,outputNumber:2,variables:args.variables};
    }
  }
  const cleanBase = (args.originalLibraryFile?.fileNameWithoutExtension || parsed.name)
    .replace(/(_(salvaged|healed|eac3|temp|singlepass)|-TdarrCacheFile-[A-Za-z0-9_-]+)$/g, "");

  try {
  const audioPrecheckStartedAt=Date.now();
  await precheckRetainedSourceAudio();
    if(quarantinedCandidate)persistPrechecks(quarantinedCandidate);
  log(`[Audio precheck] Completed in ${((Date.now()-audioPrecheckStartedAt)/1000).toFixed(2)}s.`);
  reportWorkerProgress(args.updateWorker,{percentage:10,fps:0,status:"Preparing: reserve cache and build output"},initialWorkerProgressDetails);
  // Cache reservations permit concurrent jobs while coordinating available space.
  const reservationRootDir = process.env.TDARR_RESERVATION_ROOT || "/transcode_cache";
  const envMinFreeMB = parseInt(process.env.TDARR_MIN_FREE_SPACE_MB || args.variables?.user?.min_cache_free_mb || 0, 10);
  const minFloorMB = Number.isSafeInteger(envMinFreeMB) && envMinFreeMB > 0 ? envMinFreeMB : 20480;
  const envMinRamFreeMB = parseInt(process.env.TDARR_MIN_RAM_FREE_MB || args.variables?.user?.min_ram_free_mb || 0, 10);
  const minRamFloorMB = Number.isSafeInteger(envMinRamFreeMB) && envMinRamFreeMB > 0 ? envMinRamFreeMB : 2048;
  const envMinSystemRamFreeMB = parseInt(process.env.TDARR_MIN_SYSTEM_RAM_FREE_MB || args.variables?.user?.min_system_ram_free_mb || 0, 10);
  const minSystemRamFloorMB = Number.isSafeInteger(envMinSystemRamFreeMB) && envMinSystemRamFreeMB > 0 ? envMinSystemRamFreeMB : 4096;
  const reservedOutputBytes = ((originalSnapshot.size * 5n + 3n) / 4n) + 64n * 1024n * 1024n;
  const maxOutputBytes = reservedOutputBytes - 32n * 1024n * 1024n;
  const candidates = [];
  // Prefer bounded /dev/shm when capacity allows; configured disk paths remain fallbacks.
  for (const candidate of ["/dev/shm", process.env.TDARR_DEDICATED_CACHE, args.variables?.user?.dedicated_cache_dir, args.workDir, "/transcode_cache", "/temp", "/mnt/cache", "/app/unmappedNodeCache"]) {
    if (typeof candidate !== "string" || !path.isAbsolute(candidate) || !fs.existsSync(candidate)) continue;
    try {
      const real = fs.realpathSync(candidate);
      const fsType = fs.statfsSync(real,{bigint:true}).type;
      if (typeof fsType !== "bigint") { log(`[Cache reservation] Cannot determine filesystem type for ${candidate}; skipping.`); continue; }
      const magic = BigInt.asUintN(32,fsType);
      if (magic === 2240043254n) { log(`[Cache reservation] Skipping unbounded ramfs candidate ${candidate}.`); continue; }
      if (!candidates.includes(real)) candidates.push(real);
    } catch (err) { log(`[Cache reservation] Cannot inspect ${candidate}; trying the next cache.`); }
  }
  let selectedDir = null;
  for (const candidate of candidates) {
    try {
      const real = fs.realpathSync(candidate);
      const magic = BigInt.asUintN(32,fs.statfsSync(real,{bigint:true}).type);
      const isRamCache = magic === 16914836n;
      const floorBytes = BigInt(isRamCache ? minRamFloorMB : minFloorMB) * 1024n * 1024n;
      const systemRamFloorBytes = BigInt(isRamCache ? minSystemRamFloorMB : 0) * 1024n * 1024n;
      const handle = await reserveCapacity({root:reservationRootDir,candidate:real,bytes:reservedOutputBytes,floorBytes,systemRamFloorBytes});
      args.variables.user.cache_reservation = handle;
      selectedDir = real;
      log(`[Cache reservation] Reserved ${reservedOutputBytes} bytes on ${real} (${isRamCache ? "RAM" : "disk"}); other jobs may run when capacity permits.`);
      break;
    } catch (err) {
      if (/Insufficient available capacity for reservation/.test(String(err.message || err))) {
        log(`[Cache reservation] Insufficient available capacity on ${candidate}; trying the next candidate.`);
        continue;
      }
      throw err;
    }
  }
  if (!selectedDir) throw Error("No cache directory has enough unreserved space for this job");

  // A per-job directory prevents collisions for identical basenames.
  const targetDir = makeJobDir(selectedDir);
  const outputPath = path.join(targetDir, `${cleanBase}.mkv`);
  args.variables.user.safety_temp_dir = targetDir;
  await registerReservationWorkspace(args.variables.user.cache_reservation, targetDir);
  args.variables.user.safety_temp_output = outputPath;
  if (quarantinedCandidate) {
    const cachedCandidateSize = BigInt(fs.statSync(quarantinedCandidate.candidatePath).size);
    if (cachedCandidateSize > reservedOutputBytes) {
      await growCapacityReservation(args.variables.user.cache_reservation,cachedCandidateSize,0n,{marginBytes:64n*1024n*1024n});
      log(`[Cache reservation] Expanded scratch capacity for ${cachedCandidateSize}-byte quarantined candidate.`);
    }
    fs.copyFileSync(quarantinedCandidate.candidatePath,outputPath,fs.constants.COPYFILE_EXCL);
    if (hashFilePath(outputPath) !== quarantinedCandidate.candidateHash) {
      try { fs.unlinkSync(outputPath); } catch (_) {}
      throw Error('Quarantined candidate changed while copying into the current job cache');
    }
    args.variables.user.quarantine_entry=quarantinedCandidate;
    log(`[Quarantine] Copied the stored candidate into this job cache for current validation; the quarantine original remains untouched until replacement succeeds.`);
  }
  if (!quarantinedCandidate && normalizedAssContents.size > 0) {
    for (const [streamIndex, normAssText] of normalizedAssContents) {
      const normAssPath = path.join(targetDir, `normalized-sub-${streamIndex}.ass`);
      fs.writeFileSync(normAssPath, normAssText, {mode: 0o600});
      normalizedAssPaths.set(streamIndex, normAssPath);
    }
    log(`[Subtitle precheck] Wrote ${normalizedAssPaths.size} normalized ASS/SSA stream file(s) into job scratch.`);
  }


  // 7. Chapter Boundary Guard (Seek Healing for out-of-bounds chapter end_time against video/container duration)
  let clampedMetaPath = null;
  let hasClampedChapters = false;
  try {
    const probeChaptersRaw = execFileSync("ffprobe", [
      "-v", "error", "-show_chapters", "-print_format", "json", inputPath
    ], { encoding: "utf8" });
    const chapData = JSON.parse(probeChaptersRaw);
    const chaps = chapData?.chapters || [];
    if (chaps.length > 0 && durationSec > 0) {
      const lastChap = chaps[chaps.length - 1];
      const lastEndSec = parseFloat(lastChap.end_time || 0);
      if (lastEndSec > durationSec + 0.1) {
        log(`[Chapter Boundary Guard] Last chapter end_time (${lastEndSec}s) exceeds video/container duration (${durationSec}s). Clamping chapter boundaries.`);
        const maxMs = Math.round(durationSec * 1000);
        const metaLines = [";FFMETADATA1"];
        chaps.forEach((c, idx) => {
          const startMs = Math.min(Math.round(parseFloat(c.start_time || 0) * 1000), maxMs);
          let endMs = Math.round(parseFloat(c.end_time || 0) * 1000);
          if (endMs > maxMs) {
            endMs = maxMs;
          }
          metaLines.push("[CHAPTER]", "TIMEBASE=1/1000", `START=${startMs}`, `END=${endMs}`);
          const title = c.tags?.title || `Chapter ${idx + 1}`;
          metaLines.push(`title=${title}`);
        });
        clampedMetaPath = path.join(targetDir, `${cleanBase}_chapters.txt`);
        fs.writeFileSync(clampedMetaPath, metaLines.join("\n"));
        hasClampedChapters = true;
      }
    }
  } catch (chapErr) {
    // Non-fatal if chapter probe fails
  }

  // Helper to append audio & subtitle mappings to any FFmpeg command array
  const langDisplayMap = {
    eng: "English",
    jpn: "Japanese",
    zho: "Chinese",
    ita: "Italian",
    spa: "Spanish",
    und: "Audio"
  };
  const codecDisplayMap = {
    opus: "Opus",
    eac3: "E-AC-3",
    ac3: "AC3",
    dts: "DTS",
    aac: "AAC",
    flac: "FLAC",
    truehd: "TrueHD",
    alac: "ALAC",
    mp3: "MP3",
    vorbis: "Vorbis"
  };

  const appendAudioAndSubArgs = (cmdArgs) => {
    if (finalAudioStreams.length > 0) {
      finalAudioStreams.forEach((s, idx) => {
        cmdArgs.push("-map", `0:${s.index}`);
        const ch = parseInt(s.channels || 0, 10);
        const c = (s.codec_name || "").toLowerCase();
        const prof = (s.profile || "").toLowerCase();
        let actualCodec = "Audio";
        let finalCh = ch || 2;

        // Preserve the selected source audio bitstream and channel layout unchanged.
        cmdArgs.push(`-c:a:${idx}`, "copy");
        if (audioTimestampRepairs.has(s.index)) cmdArgs.push(`-bsf:a:${idx}`, audioTimestampRepairBsf());
        if (c === "dts" && prof.includes("dts-hd")) {
          actualCodec = "DTS-HD MA";
        } else {
          actualCodec = codecDisplayMap[c] || (c ? c.toUpperCase() : "Audio");
        }

        // Dynamic Audio Title Normalization & Codec Tag Sanitization
        const chLayout = finalCh === 6 ? "5.1" : (finalCh === 8 ? "7.1" : (finalCh === 1 ? "Mono" : "2.0"));
        const canonLang = normalizeLang(s.tags?.language || s.tags?.LANGUAGE || "und");
        const langName = langDisplayMap[canonLang] || (canonLang ? canonLang.toUpperCase() : "Audio");
        const rawTitle = String(s.tags?.title || s.tags?.TITLE || "");
        const strippedTitle = rawTitle
          .replace(/\[[^\]]*\]|\([^)]*\)/g, " ")
          .replace(/\b(x264|x265|h264|h265|hevc|av1|10b|10bit|8bit|\d+\s*kbps)\b/gi, " ")
          .replace(/\s+/g, " ")
          .trim();
        const isGenericOrEmpty = !strippedTitle || /^(english|eng|japanese|jap|jpn|chinese|zho|chi|mandarin|cantonese|italian|ita|spanish|spa|undetermined|und|stereo|surround|mono|audio|default|main|original|track\s*\d+|\d+\.\d+|aac|ac-?3|e-?ac-?3|ddp?|opus|dts(?:-hd)?(?:\s*ma)?|truehd|flac|pcm|\s|-|\/|:)+$/i.test(strippedTitle);
        const correctedTitle = isGenericOrEmpty
          ? `${langName} [${actualCodec} ${chLayout}]`
          : `${strippedTitle} [${actualCodec} ${chLayout}]`;
        cmdArgs.push(`-metadata:s:a:${idx}`, `title=${correctedTitle}`);
      });

      // Enforce Surround = default and Stereo = non-default (0) when both exist
      const hasSurround = finalAudioStreams.some(s => parseInt(s.channels || 0, 10) > 2);
      const hasStereo = finalAudioStreams.some(s => {
        const ch = parseInt(s.channels || 0, 10);
        return ch > 0 && ch <= 2;
      });
      if (hasSurround && hasStereo) {
        let defaultSet = false;
        finalAudioStreams.forEach((s, idx) => {
          if (parseInt(s.channels || 0, 10) > 2 && !defaultSet) {
            cmdArgs.push(`-disposition:a:${idx}`, "default");
            defaultSet = true;
          } else {
            cmdArgs.push(`-disposition:a:${idx}`, "0");
          }
        });
      }
    } else {
      cmdArgs.push("-an");
    }

    if (finalSubStreams.length > 0) {
      finalSubStreams.forEach((s, idx) => {
        const c = (s.codec_name || "").toLowerCase();
        const cid = (s.codec_tag_string || s.codec_id || "").toLowerCase();
        if (!normalizedAssInputIndex.has(s.index)) cmdArgs.push("-map", `0:${s.index}`);
        if (shouldConvertSubToSrt(s)) {
          cmdArgs.push(`-c:s:${idx}`, "srt");
        } else if (normalizedAssInputIndex.has(s.index)) {
          cmdArgs.push("-map", `${normalizedAssInputIndex.get(s.index)}:0`, `-c:s:${idx}`, "copy");
          for (const [tagKey, tagVal] of Object.entries(s.tags || {})) {
            if (tagKey && tagVal !== undefined && tagVal !== null && !/^(_STATISTICS_|BPS|DURATION|NUMBER_OF_)/i.test(tagKey)) {
              cmdArgs.push(`-metadata:s:s:${idx}`, `${tagKey}=${tagVal}`);
            }
          }
          const subDispositions = Object.entries(s.disposition || {}).filter(([,v]) => Number(v) === 1).map(([k]) => k);
          cmdArgs.push(`-disposition:s:${idx}`, subDispositions.length ? subDispositions.join("+") : "0");
        } else {
          cmdArgs.push(`-c:s:${idx}`, "copy");
          if (c === "hdmv_pgs_subtitle" || ['ass','ssa'].includes(c)) {
            cmdArgs.push(`-bsf:s:${idx}`, "setts=pts=if(eq(PTS\\,NOPTS)\\,NOPTS\\,max(PTS\\,PREV_OUTPTS)):dts=if(eq(DTS\\,NOPTS)\\,NOPTS\\,max(DTS\\,PREV_OUTDTS))");
          }
        }
      });
    } else {
      cmdArgs.push("-sn");
    }
  };

  // 8. Assemble Single-Pass FFmpeg Execution Command
  const extractFfmpegError = (stderrStr) => {
    const lines = String(stderrStr || "")
      .split("\n")
      .map(l => l.trim())
      .filter(l => l && !l.startsWith("configuration:") && !l.startsWith("lib") && !l.startsWith("ffmpeg version"));
    const specific = lines.filter(l => /\b(?:error|failed|unsupported|invalid|cannot|could not|only one of them|ratecontrol)\b/i.test(l)
      && !/discarding stream metadata .* because the stream is being re-encoded/i.test(l));
    const causal = specific.filter(l => !/task finished with error|terminating thread with error|conversion failed/i.test(l));
    const chosen = causal.length ? causal.slice(-6) : lines.slice(-12);
    return chosen.join(" | ").substring(0, 1200);
  };

  const runFfmpeg = (useHybrid = false, forceStreamCopy = false, useSoftwareFallback = false) => {
    const cmdArgs = ["-y", "-xerror", "-progress", "pipe:1", "-nostats", "-fflags", forceStreamCopy ? "+genpts+igndts" : "+genpts"];
    const doCopyVideo = isAlreadyAV1 || forceStreamCopy;

    if (!doCopyVideo && !useSoftwareFallback) {
      // Both Full Hardware and Hybrid modes require VAAPI->QSV device context for av1_qsv encoder
      cmdArgs.push(
        "-init_hw_device", `vaapi=va:${gpuDevice}`,
        "-init_hw_device", "qsv=hw@va",
        "-filter_hw_device", "hw"
      );
      if (!useHybrid) {
        // Full Hardware QSV Decode
        cmdArgs.push(
          "-hwaccel", "qsv",
          "-hwaccel_device", "hw",
          "-hwaccel_output_format", "qsv",
          "-extra_hw_frames", "64"
        );
      }
    }

    if (hdrMasterOverride && !forceStreamCopy) cmdArgs.push("-mastering_display", hdrMasterOverride);
    if (hdrLightOverride && !forceStreamCopy) cmdArgs.push("-content_light", hdrLightOverride);
    if ((useHybrid || useSoftwareFallback) && !forceStreamCopy) cmdArgs.push("-threads", String(getDecodeThreadCount()));
    cmdArgs.push("-i", inputPath);
    if (is12Bit && !forceStreamCopy) cmdArgs.push("-sws_dither", "ed");

    if (hasClampedChapters && clampedMetaPath) {
      cmdArgs.push("-i", clampedMetaPath, "-map_metadata", "0", "-map_chapters", "1");
    }
    normalizedAssInputIndex.clear();
    if (normalizedAssPaths.size > 0) {
      let nextAssInputIdx = (hasClampedChapters && clampedMetaPath) ? 2 : 1;
      const sourceFormatStartTime = Number(args.inputFileObj?.ffProbeData?.format?.start_time || 0);
      for (const [streamIndex, normPath] of normalizedAssPaths) {
        if (Number.isFinite(sourceFormatStartTime) && sourceFormatStartTime !== 0) {
          cmdArgs.push("-itsoffset", String(-sourceFormatStartTime));
        }
        cmdArgs.push("-i", normPath);
        normalizedAssInputIndex.set(streamIndex, nextAssInputIdx++);
      }
    }

    // Video Mapping & Encoding / Stream-Copy Arguments
    cmdArgs.push("-map", `0:${mainVideo.index}`);
    // Prevent FFmpeg's automatic sync mode from silently dropping or duplicating decoded frames.
    if (!doCopyVideo) cmdArgs.push("-fps_mode:v", "passthrough");
    if (hdrClass === "untagged") cmdArgs.push(...untaggedColorRangeArgs(hdrClass,sdrSource));
    if (doCopyVideo) {
      cmdArgs.push("-c:v", "copy");
    } else {
      const baseVideoFilter=hdrClass==="dovi5_hdr10"
        ? `libplacebo=apply_dolbyvision=true:colorspace=bt2020nc:color_primaries=bt2020:color_trc=smpte2084:range=tv:tonemapping=clip:peak_detect=false:format=${useSoftwareFallback?"yuv420p10le":"p010le"},sidedata=mode=delete:type=DOVI_METADATA`
        : useSoftwareFallback
          ? "sidedata=mode=delete:type=DOVI_METADATA,format=yuv420p10le"
          : useHybrid ? "format=p010le" : is10Bit ? "vpp_qsv" : "vpp_qsv=format=p010";
      const sourceHasContentLight=(hdrSource?.side_data_list || []).some(x=>x.side_data_type==="Content light level metadata");
      const videoFilter=composeVideoFilterChain(baseVideoFilter,{
        removeHdr10Plus:hdrClass==="hdr10plus_hdr10" || hdrClass==="dovi81_hdr10plus_hdr10" || hdrClass==="dovi7_hdr10plus_hdr10",
        removeContentLight:isHdr && !sourceHasContentLight
      });
      cmdArgs.push("-vf",videoFilter);

      if (isHdr) {
        if (isHlg) {
          cmdArgs.push("-color_primaries", "bt2020", "-color_trc", "arib-std-b67", "-colorspace", "bt2020nc");
        } else {
          cmdArgs.push("-color_primaries", "bt2020", "-color_trc", "smpte2084", "-colorspace", "bt2020nc");
          if (hdrClass === "dovi5_hdr10") cmdArgs.push("-color_range", "tv");
        }
      } else if (!isHdr && hdrClass === "sdr" && sdrSource) {
        if (!isUnknownColorValue(sdrSource.color_primaries)) cmdArgs.push("-color_primaries", sdrSource.color_primaries);
        if (!isUnknownColorValue(sdrSource.color_transfer)) cmdArgs.push("-color_trc", sdrSource.color_transfer);
        if (!isUnknownColorValue(sdrSource.color_space)) cmdArgs.push("-colorspace", sdrSource.color_space);
        if (!isUnknownColorValue(sdrSource.color_range)) cmdArgs.push("-color_range", sdrSource.color_range);
      }

      if (useSoftwareFallback) {
        cmdArgs.push("-c:v", "libsvtav1", "-preset", "8", "-crf", "28", "-svtav1-params", "lp=4", "-dolbyvision", "0");
      } else {
        cmdArgs.push(
          "-c:v", "av1_qsv",
          "-preset", "slow",
          "-global_quality", `${quality}`,
          "-extbrc", "1",
          "-adaptive_i", "1",
          "-adaptive_b", "1",
          "-b_strategy", "1",
          "-g", "120"
        );
      }
    }

    // Stamp flow signature on all encoded and bloat-fallback files to prevent re-encode loops
    if (!doCopyVideo || forceStreamCopy) {
      cmdArgs.push("-metadata:g", forceStreamCopy ? "encoded_by=ArcAV1_SeekHeal_V15" : useSoftwareFallback ? "encoded_by=ArcAV1_SVTAV1_HDRFallback_V15" : "encoded_by=ArcAV1_QSV_V15");
    }

    // Audio & Subtitle Mappings
    appendAudioAndSubArgs(cmdArgs);
    for(const stream of retainedAttachmentStreams)cmdArgs.push("-map",`0:${stream.index}`);
    if(retainedAttachmentStreams.length)cmdArgs.push("-c:t","copy");

    // Purge Junk Data/Attachments & Apply Seek-Healing Muxer Stability Flags
    cmdArgs.push(
      "-map", "-0:d?",
      "-max_interleave_delta", "10000000",
      "-avoid_negative_ts", "make_zero",
      "-max_muxing_queue_size", "2048",
      ...(!forceStreamCopy ? ["-fs", String(maxOutputBytes)] : []),
      outputPath
    );

    log(`[Arc AV1 Single-Pass] Executing: ${ffmpegBin} ${cmdArgs.join(" ")}`);
    const progressStart=forceStreamCopy?80:10,progressEnd=forceStreamCopy?82:80;
    // Encodes stop at source size. Remux file-size limits grow only after the shared cache ledger grants capacity.
    const processSizeLimit=forceStreamCopy?reservedOutputBytes:sourceBytes;
    const processReason=forceStreamCopy
      ? "Size guard fallback: stream-copy the source video with seek-healing mux flags; preserve audio/subtitle processing."
      : `${softwareHdrFallback ? "SVT-AV1 encode at CRF 28" : `Arc QSV AV1 encode at ICQ ${quality}`}; validate the resulting video, color metadata, audio, and subtitles.`;
    const workerDetails={
      CLIType:ffmpegBin,
      preset:cmdArgs.join(" "),
      workerLog:processReason,
      status:forceStreamCopy?"Fallback: seek-healing remux":softwareHdrFallback?"Encoding: SVT-AV1 at CRF 28":`Encoding: Arc QSV AV1 at ICQ ${quality}`,
      sourceFileSizeInBytes:sourceBytes,
      outputPath,
      lastPluginDetails:{
        source:"Community",
        id:"arc_av1_monolithic",
        number:"1/1"
      }
    };
    const remuxCapacity=forceStreamCopy?{
      outputPath,
      initialBytes:reservedOutputBytes,
      headroomBytes:512n*1024n*1024n,
      chunkBytes:1024n*1024n*1024n,
      grow:(requiredBytes,usedBytes)=>growCapacityReservation(args.variables.user.cache_reservation,requiredBytes,usedBytes,{marginBytes:64n*1024n*1024n}),
      onLimit:bytes=>{
        args.variables.user.cache_reservation_bytes=String(bytes);
        log(`[Cache reservation] Expanded seek-healing remux capacity to ${bytes} bytes on ${targetDir}.`);
      }
    }:undefined;
    const useUnlimitedRlimit = hdrClass === "dovi5_hdr10" && !forceStreamCopy;
    const processCapacity = remuxCapacity || (useUnlimitedRlimit ? {
      outputPath,
      initialBytes: sourceBytes,
      stopOnLimit: true,
      pollMs: 100
    } : undefined);
    const ffmpegEnv = useUnlimitedRlimit
      ? {VK_ICD_FILENAMES:INTEL_VULKAN_ICD,VK_DRIVER_FILES:INTEL_VULKAN_ICD}
      : undefined;
    return runLimitedFfmpeg({command:"prlimit",argv:[`--fsize=${useUnlimitedRlimit ? "unlimited" : `${processSizeLimit}:unlimited`}`, "--", ffmpegBin, ...cmdArgs],durationSec,updateWorker:args.updateWorker,workerDetails,progressStart,progressEnd,capacity:processCapacity,env:ffmpegEnv});
  };

  if (quarantinedCandidate) {
    quality = quarantinedCandidate.kind === "seek_heal_remux" ? null : quarantinedCandidate.kind === "svt_av1_encode" ? 28 : selectedQuality;
    pipelineMode = quarantinedCandidate.kind === "seek_heal_remux" ? "Quarantined seek-heal remux revalidation" : quarantinedCandidate.kind === "svt_av1_encode" ? "Quarantined SVT-AV1 candidate revalidation" : "Quarantined Arc QSV AV1 candidate revalidation";
    args.variables.user.quarantine_entry = quarantinedCandidate;
  }
  log(`[Arc AV1] Processing ${inputPath} using ${qualityLabel} ${quality}; ${pipelineMode}`);
  const sourceBytes = Number(originalSnapshot.size);
  if (!Number.isSafeInteger(sourceBytes) || sourceBytes < 1) throw new Error("Original size is invalid");
  args.variables.user.original_size_mb = sourceBytes / (1024 * 1024);
  let isBloat = quarantinedCandidate?.kind === "seek_heal_remux";
  if (isBloat && args.variables.user.hdr_conversion) args.variables.user.hdr_conversion = "Original dynamic HDR / Dolby Vision video stream preserved (seek-heal remux)";
  const attempt = quarantinedCandidate
    ? {ok:true,quality,result:{ok:true,size:fs.statSync(outputPath).size,ffmpeg:{status:0,stderr:""}}}
    : await runSingleQuality(quality, sourceBytes, async (q) => {
    if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath);
    let result = await runFfmpeg(needsProactiveHybrid, false, softwareHdrFallback);
    if (result.error) return {ok:false, ffmpeg:result};
    const reachedLimit = r => fs.existsSync(outputPath) && fs.statSync(outputPath).size >= sourceBytes && (r.signal === 'SIGXFSZ' || !!r.capacityError || /file too large/i.test(String(r.stderr || '')));
    if (reachedLimit(result)) { log(`[Size guard] ${qualityLabel} ${q} encode hit the source-size cap.`); return {ok:true,size:sourceBytes,ffmpeg:result}; }
    const decodeFailure = /error while decoding|failed to decode|decoder[^\n]*(?:error|failed)|error submitting packet to decoder|failed to get (?:a )?frame/i.test(String(result.stderr || ""));
    if (result.status !== 0 && !needsProactiveHybrid && !softwareHdrFallback && decodeFailure) {
      log(`[Arc AV1] Full GPU decode failed at ICQ ${q}: ${extractFfmpegError(result.stderr)}. Trying CPU decode with Arc encode.`);
      if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath);
      result = await runFfmpeg(true, false);
      pipelineMode = `Hybrid (CPU Decode + Arc QSV AV1 Encode)`;
      if (reachedLimit(result)) { log(`[Size guard] ${qualityLabel} ${q} encode hit the source-size cap.`); return {ok:true,size:sourceBytes,ffmpeg:result}; }
    }
    if (result.status !== 0 || !fs.existsSync(outputPath)) return {ok:false, ffmpeg:result};
    const size = fs.statSync(outputPath).size;
    log(`[Arc AV1] ${qualityLabel} ${q} produced ${size} bytes; source ${sourceBytes} bytes.`);
    return {ok:true, size, ffmpeg:result};
  });
  let res = attempt.result?.ffmpeg || {status: 1, stderr: `No smaller output at ${qualityLabel} ${attempt.quality}`};
  if (!attempt.ok && attempt.reason !== "encoder") {
    if (attempt.reason !== "quality_floor") log(`[Arc AV1] Could not verify a valid output size at ${qualityLabel} ${attempt.quality}.`);
    if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath);
    res = {status:1, qualityFloor:attempt.reason === "quality_floor", stderr:`No smaller output at ${qualityLabel} ${attempt.quality}: ${attempt.reason}`};
  }

  // Cleanup temporary clamped chapters file if created
  const cleanupChapters = () => {
    if (clampedMetaPath && fs.existsSync(clampedMetaPath)) {
      try { fs.unlinkSync(clampedMetaPath); } catch (_) {}
    }
  };

  if (res.qualityFloor) {
    if(mustRetainOriginalAtQualityFloor(hdrClass)){
      try { if(fs.existsSync(outputPath))fs.unlinkSync(outputPath); } catch(_) {}
      cleanupChapters();
      log(`[Size guard] No smaller output at ${qualityLabel} ${attempt.quality}; skipping source-video remux because this HDR conversion must remove dynamic metadata. Original retained.`);
      return {outputFileObj:args.inputFileObj,outputNumber:2,variables:args.variables};
    }
    log(`[Size guard] No smaller output at ${qualityLabel} ${attempt.quality}; trying a source-video stream-copy remux with seek healing.`);
    try { if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath); } catch (_) {}
    const remuxRes = await runFfmpeg(false, true);
    cleanupChapters();
    if (remuxRes.status !== 0 || !fs.existsSync(outputPath)) {
      try { if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath); } catch (_) {}
      const remuxError = extractFfmpegError(remuxRes.stderr);
      const remuxExit = remuxRes.capacityError ? `Cache reservation growth stopped the remux: ${remuxRes.capacityError.message || remuxRes.capacityError}` : remuxRes.error ? `FFmpeg could not start: ${remuxRes.error.message || remuxRes.error}` : `FFmpeg exit ${remuxRes.status ?? "unknown"}${remuxRes.signal ? ` (${remuxRes.signal})` : ""}`;
      const remuxOutput = fs.existsSync(outputPath) ? `output ${fs.statSync(outputPath).size} bytes` : "output missing";
      const reason = `${remuxExit}; ${remuxOutput}${remuxError ? `; stderr: ${remuxError}` : ""}`;
      log(`[Size guard] Seek-healing remux failed (${reason}); original retained.`);
      return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
    }
    const remuxBytes = fs.statSync(outputPath).size;
    const remuxLimit=remuxRes.fileSizeLimit ?? reservedOutputBytes;
    if (BigInt(remuxBytes) > remuxLimit) {
      try { fs.unlinkSync(outputPath); } catch (_) {}
      log(`[Cache reservation] Seek-healing remux exceeded its granted output capacity (${remuxBytes} bytes vs ${remuxLimit}); original retained.`);
      return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
    }
    isBloat = true;
    if (args.variables.user.hdr_conversion) args.variables.user.hdr_conversion = "Original dynamic HDR / Dolby Vision video stream preserved (seek-heal remux)";
    quality = null;
    pipelineMode = "Size Bloat Fallback (Original Video Stream-Copy + Seek Healed)";
    res = {status:0,stderr:remuxRes.stderr || ""};
    log(`[Size guard] Seek-healing remux completed at ${remuxBytes} bytes (source ${sourceBytes}); ${remuxBytes>sourceBytes?"the repaired output is larger than source and will be preserved":"the repaired output is smaller than source"}. Validating before replacement.`);
  }
  if (res.status !== 0 || !fs.existsSync(outputPath)) {
    cleanupChapters();
    const errTail = extractFfmpegError(res.stderr);
    const errReason = res.error
      ? `Unable to start the size-limited encoder: ${res.error.message || res.error}`
      : errTail
      ? `FFmpeg exit ${res.status}: ${errTail}`
      : `FFmpeg process exited with status ${res.status}`;
    log(`[Arc AV1 Single-Pass] Transcode execution failed critically: ${errReason}`);
    const totalDurationStr = formatDuration(Date.now() - startEpoch);
    const failPayload = {
      embeds: [{
        title: `❌ ${titleName}`,
        description: [
          `⚠️ **Error:** \`${errReason.replace(/`/g, "'")}\``,
          `⏱️ **Duration:** ${totalDurationStr}`
        ].join("\n"),
        color: 15158332,
        footer: { text: "Tdarr AV1 Flow • Transcode Failure Alert" },
        timestamp: new Date().toISOString()
      }]
    };
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  // 9. 7-Tier Dual-Condition Dynamic Size & Quality Guard
  const outputStat = fs.statSync(outputPath);
  const newSizeMB = outputStat.size / (1024 * 1024);
  const origGB = rawSizeMB > 0 ? (rawSizeMB / 1024) : 0;
  const ratioPct = rawSizeMB > 0 ? ((newSizeMB / rawSizeMB) * 100) : 100;

  const is4K = width >= 3840 || height >= 1600;
  const is1080p = (width >= 1920 || height >= 1000) && !is4K;

  let tierName = "Tier 7: 720p / SD / Low-Res";
  let minRatioPct = 6.0;
  let maxRatioPct = 115.0;
  let minAbsoluteMB = 25;

  if (is4K) {
    if (origGB >= 40) {
      tierName = "Tier 1: Massive 4K UHD Remux (>= 40 GB)";
      minRatioPct = 1.5; maxRatioPct = 85.0; minAbsoluteMB = 300;
    } else if (origGB >= 15) {
      tierName = "Tier 2: Standard 4K Web/Rip (15 - 40 GB)";
      minRatioPct = 3.0; maxRatioPct = 95.0; minAbsoluteMB = 250;
    } else {
      tierName = "Tier 3: Light 4K Web-DL (< 15 GB)";
      minRatioPct = 4.0; maxRatioPct = 105.0; minAbsoluteMB = 200;
    }
  } else if (is1080p) {
    if (origGB >= 20) {
      tierName = "Tier 4: Heavy 1080p Remux (>= 20 GB)";
      minRatioPct = 2.5; maxRatioPct = 90.0; minAbsoluteMB = 150;
    } else if (origGB >= 5) {
      tierName = "Tier 5: Standard 1080p Blu-ray/Web (5 - 20 GB)";
      minRatioPct = 4.0; maxRatioPct = 105.0; minAbsoluteMB = 100;
    } else {
      tierName = "Tier 6: Compressed 1080p (< 5 GB)";
      minRatioPct = 5.0; maxRatioPct = 110.0; minAbsoluteMB = 50;
    }
  }

  // Require at least 15% size reduction when re-encoding an already-AV1 file
  if (isOversizedAV1) {
    maxRatioPct = Math.min(maxRatioPct, 85.0);
    tierName += " • Oversized AV1 Re-Encode (<=85% Target)";
  }

  // Dual-Condition Corrupt Protection (or < 1% on remux)
  const isUndersized = isAlreadyAV1
    ? (ratioPct < 1.0 || newSizeMB < 0.1)
    : ((ratioPct < minRatioPct) && (newSizeMB < minAbsoluteMB));
  // isBloat is set only by the strictly smaller, validated seek-heal fallback.

  if (isUndersized) {
    if (quarantinedCandidate) {
      const sizeFailureReport={version:1,outcome:"rejected",stage:"size_policy",checks:[{stage:"size_policy",outcome:"rejected",code:"candidate_size_policy"}],failure:{outcome:"rejected",stage:"size_policy",code:"candidate_size_policy",message:`Quarantined candidate failed the current size floor (${newSizeMB.toFixed(2)} MB, ${ratioPct.toFixed(1)}% of source).`}};
      args.variables.user.validation_report=sizeFailureReport;
      try {
        quarantinedCandidate=await updateQuarantineFailure(quarantinedCandidate,sizeFailureReport);
        args.variables.user.quarantine_entry=quarantinedCandidate;
        log(`[Quarantine] Candidate remains stored after failing the current size policy (${quarantinedCandidate.candidatePath}).`);
      } catch (quarantineError) {
        log(`[Quarantine] Could not update the stored candidate's size-policy report: ${quarantineError.message || quarantineError}; the candidate remains untouched.`);
      }
    }

    cleanupChapters();
    log(`[Size Guard] Output file undersized: ${newSizeMB.toFixed(2)} MB (${ratioPct.toFixed(1)}%). Deleting corrupt cache.`);
    try { fs.unlinkSync(outputPath); } catch (e) {}
    const totalDurationStr = formatDuration(Date.now() - startEpoch);
    const underPayload = {
      embeds: [{
        title: `🗑️ ${titleName}`,
        description: [
          `📁 **Cache Size:** \`${formatSize(newSizeMB)}\` *(Source was ${formatSize(rawSizeMB)})*`,
          `🛡️ **Floor:** < ${minRatioPct}% or < ${minAbsoluteMB} MB`,
          `⏱️ **Duration:** ${totalDurationStr}`
        ].join("\n"),
        color: 15158332,
        footer: { text: "Tdarr AV1 Flow • Corrupt File Guard" },
        timestamp: new Date().toISOString()
      }]
    };
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  cleanupChapters();

  // 10. Persist Pipeline Metadata for Post-Replace *ARR Rescan & Discord Success Notification
  // Validate the final output, including stream-copy fallbacks, before replacing anything
  try {
    const expectedVideoCodec = (isAlreadyAV1 || isBloat) ? vCodec : "av1";
    const expectedAudioCodecs = finalAudioStreams.map(s => s.codec_name);
    const expectedSubCodecs = finalSubStreams.map(s => {
      const c = (s.codec_name || "").toLowerCase();
      const cid = (s.codec_tag_string || s.codec_id || "").toLowerCase();
      return shouldConvertSubToSrt(s) ? "subrip" : s.codec_name;
    });

    let validationReport;
    const validateCandidate=async()=>{
      validationReport=args.variables.user.validation_report=newValidationReport();
      Object.defineProperty(validationReport,"stageLogger",{value:entry=>log(`[Validation stage] ${entry.stage}: ${entry.outcome} in ${(entry.elapsedMs/1000).toFixed(2)}s.`)});
      reportWorkerProgress(args.updateWorker,{percentage:80,fps:0,status:"Validation: output streams and metadata"});
      return await validationStage(validationReport,"candidate_validation",()=>validateOutput(ffprobeBin, inputPath, outputPath, {
        validationReport,
        codec: expectedVideoCodec,
        requireMarker: true,
        hdr10: hdrClass === "hdr10" || hdrClass === "dovi81_hdr10" || hdrClass === "dovi7_hdr10" || hdrClass === "hdr10plus_hdr10" || hdrClass === "dovi81_hdr10plus_hdr10" || hdrClass === "dovi7_hdr10plus_hdr10" || hdrClass === "dovi5_hdr10",
        optionalHdrStatic: hdrClass === "hdr10",
        hlg: hdrClass === "hlg",
        untagged: hdrClass === "untagged",
        sourceClass: hdrClass,
        sourceHdr: hdrSource,
        sdrSource,
        sourceFrameScan: frameScan,
        updateWorker: args.updateWorker,
        log,
        assertOriginalUnchanged: assertOriginalUnchanged,
        audioTimestampRepairIndices: Array.from(audioTimestampRepairs.keys()),
        outputMarker: quarantinedCandidate?.marker || (isBloat ? "ArcAV1_SeekHeal_V15" : softwareHdrFallback ? "ArcAV1_SVTAV1_HDRFallback_V15" : "ArcAV1_QSV_V15"),
        sourceVideoIndex: mainVideo.index,
        ffmpegBin,
        audioIndices: finalAudioStreams.map(s => s.index),
        subtitleIndices: finalSubStreams.map(s => s.index),
        attachmentIndices: retainedAttachmentStreams.map(s => s.index),
        audio: finalAudioStreams.length,
        subtitle: finalSubStreams.length,
        audioCodecs: expectedAudioCodecs,
        subtitleCodecs: expectedSubCodecs      }));
    };
    const clampRetryResult=await validateQsvWithSvtHdrClampFallback({
      source:qsvHdrClampRetryEligible && !softwareHdrFallback ? hdrSource : null,
      validateQsvCandidate:validateCandidate,
      encodeSvtFallback:async()=>{
        if(fs.existsSync(outputPath))fs.unlinkSync(outputPath);
        softwareHdrFallback=true;quality=28;qualityLabel="SVT-AV1 CRF";
        pipelineMode="Software SVT-AV1 HDR encode (QSV green-y clamp fallback)";
        log("[Arc AV1] QSV produced the known green-y mastering clamp; retrying once with SVT-AV1 CRF 28, then applying full candidate validation again.");
        const result=await runFfmpeg(needsProactiveHybrid,false,true);
        if(result.error)throw result.error;
        if(result.capacityError)throw result.capacityError;
        if(result.status!==0||!fs.existsSync(outputPath))throw Error(`SVT-AV1 green-y clamp retry failed (${result.status ?? result.signal ?? "unknown"}): ${extractFfmpegError(result.stderr) || "no output candidate"}`);
        if(fs.statSync(outputPath).size>=sourceBytes){fs.unlinkSync(outputPath);throw Error("SVT-AV1 green-y clamp retry did not produce a smaller candidate");}
        return outputPath;
      },
      validateSvtCandidate:async()=>await validateCandidate()
    });
    const valResult=clampRetryResult.validation;
    log(`[Output Validation] Validated output: duration ${valResult.sourceDuration ? valResult.sourceDuration + 's -> ' : ''}${valResult.outputDuration}s; 1 ${expectedVideoCodec} video stream, ${finalAudioStreams.length} audio, ${finalSubStreams.length} subtitles.`);
    for (const repair of valResult.subtitleTimestampRepairs || []) log(`[Subtitle timing] ASS/SSA stream 0:${repair.sourceIndex}: ${repair.reorderedPackets ? `reordered ${repair.reorderedPackets} out-of-order packet(s); ` : ""}normalized ${repair.adjustedPackets} timestamped packet(s); maximum adjustment ${repair.maxAdjustmentSeconds.toFixed(3)}s.`);
    for (const finding of valResult.audioTimestampFindings || []) log(`[Audio timeline] Stream 0:${finding.sourceIndex}: ${finding.message}.`);
    args.variables.user.ass_subtitle_preserved_count=isMatroskaContainer?finalSubStreams.filter(s=>['ass','ssa'].includes(String(s.codec_name||'').toLowerCase())).length:0;
    const notifyLanguageNames={eng:'English',jpn:'Japanese',spa:'Spanish',ita:'Italian',zho:'Chinese',und:'Undetermined'};
    const notifyTrackLanguages=tracks=>{
      const labels=[...new Set(tracks.map(s=>normalizeLang(s.tags?.language||s.tags?.LANGUAGE||'und')).map(code=>notifyLanguageNames[code]||code.toUpperCase()))];
      if(!labels.length)return 'none';
      return labels.slice(0,4).join(', ')+(labels.length>4?` +${labels.length-4} more`:'');
    };
    args.variables.user.audio_track_count=finalAudioStreams.length;
    args.variables.user.audio_track_languages=notifyTrackLanguages(finalAudioStreams);
    args.variables.user.subtitle_track_count=finalSubStreams.length;
    args.variables.user.subtitle_track_languages=notifyTrackLanguages(finalSubStreams);

    await validationStage(validationReport,"replacement_readiness",async()=>{
      assertOriginalUnchanged();
      const destinationPath=path.join(path.dirname(originalPath),path.basename(outputPath));
      if(destinationPath!==originalPath && fs.existsSync(destinationPath))throw Error(`Replacement destination already exists: ${destinationPath}`);
    });
    completeValidation(validationReport);
    log(`[Validation result] ${validationReport.outcome}; all required checks passed.`);
    for(const recovery of validationReport.recoveries)log(`[Validation recovery] ${recovery.code}: ${recovery.outcome}. Diagnostic: ${recovery.diagnostic}`);
  } catch (err) {
