        }

        if (typeof req.setTimeout === "function") {
          req.setTimeout(10000, () => {
            try { req.destroy(); } catch (_) {}
            finish({ ok: false, statusCode: 0, timeout: true });
          });
        }

        if (postData) req.write(postData);
        req.end();
      } catch (err) {
        finish({ ok: false, statusCode: 0, error: err });
      }
    });
  };

  try {
    const baseUrl = target.host.replace(/\/+$/, "");
    const isSonarr = target.type === "sonarr";
    const listEndpoint = `${baseUrl}/api/v3/${isSonarr ? "series" : "movie"}`;
    const listRes = await arrRequest("GET", listEndpoint, target.apiKey);

    let matchedItem = null;
    if (listRes.ok && Array.isArray(listRes.data)) {
      // Tier 1: Exact path prefix match
      matchedItem = listRes.data.find(item => {
        if (!item.path) return false;
        const p = item.path.replace(/\\/g, "/").replace(/\/+$/, "");
        return filePath === p || filePath.startsWith(p + "/");
      });

      // Tier 2: Content folder basename match (Docker volume mount agnostic)
      if (!matchedItem && contentFolder) {
        const cleanFolderLower = contentFolder.toLowerCase();
        matchedItem = listRes.data.find(item => {
          if (!item.path) return false;
          const p = item.path.replace(/\\/g, "/").replace(/\/+$/, "");
          const base = p.split("/").pop() || "";
          return base.toLowerCase() === cleanFolderLower;
        });
      }
    }

    // Tier 3: Fallback to /api/v3/parse if folder lookup did not match
    let targetId = matchedItem?.id || null;
    let matchedTitle = matchedItem?.title || contentFolder || path.posix.basename(filePath);

    if (!targetId) {
      const fileName = path.posix.basename(filePath);
      const parseUrl = `${baseUrl}/api/v3/parse?title=${encodeURIComponent(fileName)}`;
      const parseRes = await arrRequest("GET", parseUrl, target.apiKey);
      if (parseRes.ok && parseRes.data) {
        if (isSonarr && parseRes.data.series?.id) {
          targetId = parseRes.data.series.id;
          matchedTitle = parseRes.data.series.title || matchedTitle;
        } else if (!isSonarr && (parseRes.data.movie?.id || parseRes.data.movie?.movieFile?.movieId)) {
          targetId = parseRes.data.movie?.id || parseRes.data.movie?.movieFile?.movieId;
          matchedTitle = parseRes.data.movie?.title || matchedTitle;
        }
      }
    }

    if (targetId) {
      const cmdName = isSonarr ? "RescanSeries" : "RescanMovie";
      const cmdBody = isSonarr
        ? { name: "RescanSeries", seriesId: targetId }
        : { name: "RescanMovie", movieId: targetId };
      const cmdRes = await arrRequest("POST", `${baseUrl}/api/v3/command`, target.apiKey, cmdBody);
      if (cmdRes.ok) {
        log(`[ARR Notifier] Triggered ${cmdName} for '${matchedTitle}' (ID: ${targetId}) on ${target.label} (HTTP ${cmdRes.statusCode})`);
      } else {
        log(`[ARR Notifier] Warning: ${cmdName} command on ${target.label} returned HTTP ${cmdRes.statusCode}`);
      }
    } else {
      log(`[ARR Notifier] Could not resolve ${isSonarr ? "seriesId" : "movieId"} for '${contentFolder || filePath}' on ${target.label}`);
    }
  } catch (err) {
    log(`[ARR Notifier] Non-fatal error communicating with ${target.label}: ${err.message || err}`);
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables
  };
};

// Shared HTTPS Discord webhook helper.
// Never log the webhook URL or raw network error objects that may carry credentials.
const webhookHttps = require('https');

function sanitizeWebhookDetail(result) {
  if (result?.reason === 'missing_webhook') return 'TDARR_DISCORD_WEBHOOK is not configured';
  if (result?.reason === 'invalid_url') return 'invalid webhook URL';
  if (result?.reason === 'invalid_protocol') return 'invalid webhook protocol';
  const status = Number(result?.statusCode);
  if (Number.isInteger(status) && status > 0) return `HTTP ${status}`;
  if (typeof result?.code === 'string' && /^[A-Z0-9_]+$/.test(result.code)) return result.code;
  if (result?.timedOut) return 'request timed out';
  return 'request or URL error';
}

function safeWebhookLog(logFn, message) {
  if (typeof logFn !== 'function') return;
  try { logFn(message); } catch (_) {}
}

async function sendDiscordWebhook(webhookUrl, payloadData, options = {}) {
  const tag = typeof options.tag === 'string' && options.tag ? options.tag : 'Discord Notifier';
  const maxRetries = Number.isInteger(options.maxRetries) && options.maxRetries >= 1 ? options.maxRetries : 1;
  const timeoutMs = Number.isFinite(options.timeoutMs) && options.timeoutMs > 0 ? options.timeoutMs : 10000;
  const maxRetryDelayMs = Number.isFinite(options.maxRetryDelayMs) && options.maxRetryDelayMs >= 0 ? options.maxRetryDelayMs : 10000;
  const maxTotalWaitMs = Number.isFinite(options.maxTotalWaitMs) && options.maxTotalWaitMs >= 0 ? options.maxTotalWaitMs : 30000;
  const retryDelayFn = typeof options.retryDelayMs === 'function' ? options.retryDelayMs : (attempt => attempt * 2000);
  const log = options.log;

  if (typeof webhookUrl !== 'string' || !webhookUrl.trim()) {
    const res = {ok: false, reason: 'missing_webhook', statusCode: 0, code: '', timedOut: false, attempts: 0};
    safeWebhookLog(log, `[${tag}] Delivery failed: TDARR_DISCORD_WEBHOOK is not configured.`);
    return res;
  }

  let target;
  try {
    target = new URL(webhookUrl.trim());
  } catch (_) {
    const res = {ok: false, reason: 'invalid_url', statusCode: 0, code: '', timedOut: false, attempts: 0};
    safeWebhookLog(log, `[${tag}] Delivery failed (${sanitizeWebhookDetail(res)}); check TDARR_DISCORD_WEBHOOK and node connectivity.`);
    return res;
  }

  if (target.protocol !== 'https:') {
    const res = {ok: false, reason: 'invalid_protocol', statusCode: 0, code: '', timedOut: false, attempts: 0};
    safeWebhookLog(log, `[${tag}] Delivery failed (${sanitizeWebhookDetail(res)}); check TDARR_DISCORD_WEBHOOK and node connectivity.`);
    return res;
  }

  const postData = typeof payloadData === 'string' ? payloadData : JSON.stringify(payloadData);
  const headers = {
    'Content-Type': 'application/json',
    'User-Agent': 'Tdarr-DiscordNotifier/1.0',
    'Content-Length': Buffer.byteLength(postData)
  };
  let remainingWaitMs = maxTotalWaitMs;
  let lastResult = {ok: false, reason: 'request_error', statusCode: 0, code: '', timedOut: false, attempts: 0};

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const attemptResult = await new Promise(resolve => {
      let settled = false;
      let timer;
      const done = result => {
        if (settled) return;
        settled = true;
        if (typeof clearTimeout === 'function' && timer !== undefined) clearTimeout(timer);
        resolve(result);
      };

      let request;
      try {
        request = webhookHttps.request(target, {method: 'POST', headers}, response => {
          let rawBody = '';
          response.on('data', chunk => {
            if (rawBody.length < 4096) rawBody += String(chunk).slice(0, 4096 - rawBody.length);
          });
          response.on('error', err => {
            const code = typeof err?.code === 'string' && /^[A-Z0-9_]+$/.test(err.code) ? err.code : '';
            done({ok: false, retry: true, statusCode: 0, code, timedOut: false, reason: 'response_error'});
          });
          response.on('end', () => {
            const status = Number(response.statusCode) || 0;
            if (status >= 200 && status < 300) {
              done({ok: true, retry: false, statusCode: status, code: '', timedOut: false, reason: ''});
              return;
            }
            if (status === 429) {
              let retryAfter = 2000;
              try {
                const parsed = JSON.parse(rawBody);
                const rawRetry = Number(parsed?.retry_after);
                if (Number.isFinite(rawRetry) && rawRetry > 0) retryAfter = Math.ceil(rawRetry * 1000);
              } catch (_) {}
              done({ok: false, retry: true, delayMs: retryAfter, statusCode: 429, code: '', timedOut: false, reason: 'rate_limited'});
              return;
            }
            if (status >= 500) {
              done({ok: false, retry: true, statusCode: status, code: '', timedOut: false, reason: 'server_error'});
              return;
            }
            done({ok: false, retry: false, statusCode: status, code: '', timedOut: false, reason: 'rejected'});
          });
        });

        request.on('error', err => {
          const code = typeof err?.code === 'string' && /^[A-Z0-9_]+$/.test(err.code) ? err.code : '';
          done({ok: false, retry: true, statusCode: 0, code, timedOut: false, reason: 'network_error'});
        });

        if (typeof setTimeout === 'function') {
          timer = setTimeout(() => {
            try { request.destroy(); } catch (_) {}
            done({ok: false, retry: true, statusCode: 0, code: '', timedOut: true, reason: 'timeout'});
          }, timeoutMs);
        }

        if (typeof request.setTimeout === 'function') {
          request.setTimeout(timeoutMs, () => {
            try { request.destroy(); } catch (_) {}
            done({ok: false, retry: true, statusCode: 0, code: '', timedOut: true, reason: 'timeout'});
          });
        }

        if (typeof request.write === 'function') {
          request.write(postData);
          request.end();
        } else {
          request.end(postData);
        }
      } catch (err) {
        const code = typeof err?.code === 'string' && /^[A-Z0-9_]+$/.test(err.code) ? err.code : '';
        done({ok: false, retry: false, statusCode: 0, code, timedOut: false, reason: 'request_error'});
      }
    });

    lastResult = {
      ok: attemptResult.ok,
      statusCode: attemptResult.statusCode,
      code: attemptResult.code,
      timedOut: attemptResult.timedOut,
      reason: attemptResult.reason,
      attempts: attempt
    };

    if (attemptResult.ok) {
      safeWebhookLog(log, attempt === 1
        ? `[${tag}] Sent.`
        : `[${tag}] Sent on attempt ${attempt} (HTTP ${attemptResult.statusCode}).`);
      return lastResult;
    }

    if (!attemptResult.retry || attempt >= maxRetries || remainingWaitMs <= 0) {
      break;
    }

    const requestedDelay = Number.isFinite(attemptResult.delayMs)
      ? attemptResult.delayMs
      : Number(retryDelayFn(attempt, attemptResult.statusCode));
    const boundedDelay = Math.min(maxRetryDelayMs, remainingWaitMs, Math.max(1, Number.isFinite(requestedDelay) ? requestedDelay : 2000));
    remainingWaitMs -= boundedDelay;

    safeWebhookLog(log, `[${tag}] Delivery attempt ${attempt}/${maxRetries} failed (${sanitizeWebhookDetail(lastResult)}); retrying in ${boundedDelay}ms.`);
    await new Promise(resolve => {
      if (typeof setTimeout === 'function') setTimeout(resolve, boundedDelay);
      else resolve();
    });
  }

  safeWebhookLog(log, `[${tag}] Delivery failed (${sanitizeWebhookDetail(lastResult)}); check TDARR_DISCORD_WEBHOOK and node connectivity.`);
  return lastResult;
}

if (typeof module !== 'undefined') module.exports = {sendDiscordWebhook, sanitizeWebhookDetail};

module.exports = async (args) => {
  const webhookUrl = process.env.TDARR_DISCORD_WEBHOOK;
  const log = (message) => {
    try { console.log(message); } catch (_) {}
    try { if (typeof args.jobLog === "function") args.jobLog(message); } catch (_) {}
  };

  const formatSize = (mb) => {
    if (mb === undefined || mb === null || isNaN(mb) || mb <= 0) return "0 MB";
    const abs = Math.abs(mb);
    if (abs >= 1024) return (abs / 1024).toFixed(2) + " GB";
    return abs.toFixed(1) + " MB";
  };

  const formatBitrate = (kbps) => {
    if (!kbps || isNaN(kbps) || kbps <= 0) return "0 kbps";
    const k = Math.round(kbps);
    if (k >= 1000) return (k / 1000).toFixed(2) + " Mbps";
    return `${k} kbps`;
  };

  const formatDuration = (ms) => {
    if (!ms || ms < 0) return "0s";
    const totalSec = Math.max(1, Math.round(ms / 1000));
    const h = Math.floor(totalSec / 3600);
    const m = Math.floor((totalSec % 3600) / 60);
    const s = totalSec % 60;
    if (h > 0) return `${h}h ${m}m ${s}s`;
    if (m > 0) return `${m}m ${s}s`;
    return `${s}s`;
  };

  const cleanFolder = (fullPath) => {
    if (!fullPath || fullPath === "Unknown file") return "Unknown folder";
    const parts = fullPath.split("/").filter(p => p && p !== "mnt" && p !== "media");
    if (parts.length <= 1) return "Root";
    parts.pop();
    const take = Math.min(parts.length, 3);
    return parts.slice(-take).join(" / ");
  };

  const formatPipelineMode = (rawMode) => {
    if (!rawMode) return "Intel Arc GPU (Full Hardware)";
    const mode = rawMode.trim();
    if (mode.includes("Full QSV Hardware")) {
      if (mode.includes("HDR10")) return "Intel Arc GPU • HDR10";
      if (mode.includes("HLG")) return "Intel Arc GPU • HLG";
      return "Intel Arc GPU (Full Hardware)";
    }
    if (mode.includes("Hybrid")) {
      if (mode.includes("Fallback")) return "Hybrid Fallback (CPU Decode + GPU Encode)";
      if (mode.includes("CPU Decode")) return "Hybrid (CPU Decode + GPU Encode)";
      if (mode.includes("Downsample")) return "Hybrid (Color Conversion + GPU Encode)";
      return "Hybrid (CPU + GPU)";
    }
    if (mode.includes("Subtitle Normalization") || mode.includes("Seek Healing") || mode.includes("Compliant") || mode.includes("Remux")) {
      return "Fast Remux (Subtitles & Seek Repair)";
    }
    if (mode.includes("Bloat")) {
      return "Original Preserved (Bloat Protected)";
    }
    return mode;
  };

  const startEpoch = args.variables?.user?.workflow_start_epoch;
  const totalWallMs = startEpoch ? Math.max(0, Date.now() - startEpoch) : 0;
  const totalDurationStr = formatDuration(totalWallMs);

  const transcodeStartTs = args.variables?.user?.transcode_start_ts;
  const transcodeEndTs = args.variables?.user?.transcode_end_ts;
  const wasQuarantined = /^Quarantined /.test(String(args.variables?.user?.qsv_mode || ""));

  const badImageCodecs = ["mjpeg", "bmp", "png", "gif", "tiff", "otf", "ttf"];
  const vStream = (args.originalLibraryFile?.ffProbeData?.streams || []).find(s => {
    if (s.codec_type !== "video") return false;
    const c = (s.codec_name || "").toLowerCase();
    const isPic = s.disposition?.attached_pic === 1 || s.disposition?.timed_thumbnails === 1;
    return !badImageCodecs.includes(c) && !isPic;
  });
  const totalFrames = parseInt(vStream?.tags?.NUMBER_OF_FRAMES || vStream?.tags?.["NUMBER_OF_FRAMES-eng"] || vStream?.nb_frames || 0, 10);

  const filePath = args.originalLibraryFile?._id || args.inputFileObj?._id || "Unknown file";
  const fileName = filePath.split("/").pop();
  const titleName = (args.originalLibraryFile?.fileNameWithoutExtension || fileName.replace(/\.[^/.]+$/, "") || fileName)
    .replace(/(_(salvaged|healed|eac3|temp|singlepass)|-TdarrCacheFile-[A-Za-z0-9_-]+)$/g, "");
  const folderDisplay = cleanFolder(filePath);

  const origMB = args.variables?.user?.original_size_mb || args.originalLibraryFile?.file_size || 0;
  const newMB = args.variables?.user?.final_size_mb || args.inputFileObj?.file_size || 0;

  const isFallback = args.variables?.user?.is_bloat_fallback === true;
  let pipelineMode = args.variables?.user?.qsv_mode;
  if (!pipelineMode) {
    if (isFallback) {
      pipelineMode = "Size Bloat Fallback (Original Video Stream-Copy + Seek Healed)";
    } else if (transcodeStartTs && transcodeEndTs) {
      pipelineMode = "Full QSV Hardware";
    } else {
      pipelineMode = "Library Reprocessing: Subtitle Normalization & Seek Healing";
    }
  }

  let statusStr = "Transcode Complete (AV1)";
  if (transcodeStartTs && transcodeEndTs) {
    statusStr = "Transcode Complete (AV1)";
  } else if (isFallback) {
    statusStr = "Stream Healed & Remuxed *(Size Bloat Fallback)*";
  } else {
    statusStr = "Compliant • AV1 Remux Healed";
  }

  const originalBytes=Number(args.variables?.user?.original_size_bytes);
  const outputBytes=Number(args.variables?.user?.final_size_bytes);
  const hasExactSizes=Number.isSafeInteger(originalBytes)&&originalBytes>0&&Number.isSafeInteger(outputBytes)&&outputBytes>0;
  const formatByteDelta=bytes=>bytes>=1024*1024?formatSize(bytes/(1024*1024)):bytes>=1024?`${(bytes/1024).toFixed(1)} KB`:`${bytes} B`;
  let sizeStr = "";
  if (origMB > 0 && newMB > 0) {
    if (hasExactSizes) {
      const deltaBytes=originalBytes-outputBytes;
      const pct=Math.abs(deltaBytes/originalBytes*100).toFixed(1);
      const change=deltaBytes>0?`-${pct}% • ${formatByteDelta(deltaBytes)} saved`:deltaBytes<0?`+${pct}% • ${formatByteDelta(-deltaBytes)} added`:'same size';
      sizeStr = `\`${formatSize(origMB)}\` ➔ \`${formatSize(newMB)}\` **(${change})**`;
    } else {
      const ratio = ((newMB / origMB) * 100).toFixed(1);
      const diffMB = origMB - newMB;
      if (diffMB > 0.05) {
        const pctSaved = (100 - ratio).toFixed(1);
        sizeStr = `\`${formatSize(origMB)}\` ➔ \`${formatSize(newMB)}\` **(-${pctSaved}% • ${formatSize(diffMB)} saved)**`;
      } else if (diffMB < -0.05) {
        const pctAdded = (ratio - 100).toFixed(1);
        sizeStr = `\`${formatSize(origMB)}\` ➔ \`${formatSize(newMB)}\` **(+${pctAdded}% • ${formatSize(-diffMB)} added)**`;
      } else {
        sizeStr = `\`${formatSize(origMB)}\` **(size unchanged)**`;
      }
    }
  } else {
    sizeStr = `\`${formatSize(newMB || origMB)}\``;
  }

  const origVidKbps = args.variables?.user?.orig_video_kbps || (() => {
    const durSec = parseFloat(args.originalLibraryFile?.ffProbeData?.format?.duration || args.originalLibraryFile?.meta?.Duration || 0);
    if (durSec <= 0 || !origMB) return 0;
    const totKbps = Math.round((origMB * 1024 * 1024 * 8) / (durSec * 1000));
    let nonVid = 0;
    (args.originalLibraryFile?.ffProbeData?.streams || []).forEach(s => {
      if (s.codec_type === "audio") {
        const br = parseInt(s.bit_rate || s.tags?.BPS || 0, 10);
        nonVid += br > 0 ? Math.round(br / 1000) : (parseInt(s.channels || 2, 10) > 2 ? 640 : 192);
      }
    });
    return Math.max(0, totKbps - nonVid);
  })();

  const newVidKbps = args.variables?.user?.new_video_kbps || (() => {
    const durSec = parseFloat(args.originalLibraryFile?.ffProbeData?.format?.duration || args.originalLibraryFile?.meta?.Duration || 0);
    if (durSec <= 0 || !newMB) return 0;
    const totKbps = Math.round((newMB * 1024 * 1024 * 8) / (durSec * 1000));
    let nonVid = 0;
    (args.originalLibraryFile?.ffProbeData?.streams || []).forEach(s => {
      if (s.codec_type === "audio") {
        const ch = parseInt(s.channels || 2, 10);
        const c = (s.codec_name || "").toLowerCase();
        if (ch > 2 && (c !== "eac3" || ch > 6)) {
          nonVid += 640;
        } else {
          const br = parseInt(s.bit_rate || s.tags?.BPS || 0, 10);
          nonVid += br > 0 ? Math.round(br / 1000) : (ch > 2 ? 640 : 192);
        }
      }
    });
    return Math.max(0, totKbps - nonVid);
  })();

  const qualVal = args.variables?.user?.quality_value;
  let bitrateStr = "";
  if (transcodeStartTs && transcodeEndTs && origVidKbps > 0 && newVidKbps > 0) {
    const qualDesc = qualVal ? `ICQ ${qualVal}` : "ICQ mode";
    bitrateStr = `\`${formatBitrate(origVidKbps)}\` ➔ \`${formatBitrate(newVidKbps)}\` **(${qualDesc})**`;
  } else if (wasQuarantined) {
    const kind=/seek-heal/i.test(String(args.variables?.user?.qsv_mode||''))?'stored seek-heal candidate':'stored AV1 candidate';
    bitrateStr = `\`${formatBitrate(newVidKbps || origVidKbps)}\` **(${kind})**`;
  } else if (isFallback) {
    bitrateStr = `\`${formatBitrate(origVidKbps || newVidKbps)}\` **(source video copied)**`;
  } else if (origVidKbps > 0 || newVidKbps > 0) {
    bitrateStr = `\`${formatBitrate(newVidKbps || origVidKbps)}\` **(stream copy)**`;
  }

  const medium = args.variables?.user?.transcode_medium || ((args.inputFileObj?._id || "").startsWith("/dev/shm") ? "RAM" : "Disk");
  const mediumTag = medium === "RAM" ? "🧠 RAM" : "💽 Disk";

  const wasEncoded=Boolean(transcodeStartTs&&transcodeEndTs);
  const cpuDecode=/CPU Decode|Downsample/i.test(String(pipelineMode||''));
  const softwareEncode=/Software SVT-AV1/i.test(String(pipelineMode||''));
  const methodLine=wasQuarantined
    ? `🔁 **Method:** Quarantined candidate revalidated • no encode ran`
    : isFallback
      ? `🛠️ **Result:** AV1 was not smaller; validated seek-heal remux kept the original video stream.`
    : wasEncoded
      ? softwareEncode
        ? `⚙️ **Method:** Software SVT-AV1 encode at CRF 28`
        : `⚙️ **Method:** Intel Arc QSV AV1 encode • ${cpuDecode?'CPU decode/conversion':'Arc QSV decode'}`
      : `🛠️ **Method:** Validated seek-heal remux • original video stream copied`;
  const audioCount=Number(args.variables?.user?.audio_track_count||0);
  const audioLanguages=String(args.variables?.user?.audio_track_languages||'not reported');
  const subtitleCount=Number(args.variables?.user?.subtitle_track_count||0);
  const subtitleLanguages=String(args.variables?.user?.subtitle_track_languages||'not reported');
  const styledSubtitleCount=Number(args.variables?.user?.ass_subtitle_preserved_count||0);
  const subtitleStyle=styledSubtitleCount>0?` • ${styledSubtitleCount} styled ASS/SSA track${styledSubtitleCount===1?'':'s'} preserved`:'';
  const descLines = [
    `📁 **Size:** ${sizeStr}`,
    `📊 **Estimated video bitrate:** ${bitrateStr || "\`Preserved\`"}`,
    methodLine,
    `🔊 **Audio:** ${audioCount} track${audioCount===1?'':'s'} • ${audioLanguages}`,
    `💬 **Subtitles:** ${subtitleCount} track${subtitleCount===1?'':'s'} • ${subtitleLanguages}${subtitleStyle}`,
    `✅ **Validation:** Full stream, timing, subtitle, and A/V decode checks passed`,
    `⏱️ **Processing time:** ${totalDurationStr} • ${mediumTag} scratch`
  ];
  if(args.variables?.user?.validation_report?.outcome==='recovered')descLines.push('🛠️ **Verification recovery:** Arc verification failed; full software video verification passed.');
  if (args.variables?.user?.hdr_conversion) descLines.push(`🌈 **HDR:** ${args.variables.user.hdr_conversion}`);

  const payload = JSON.stringify({
    allowed_mentions: {parse: []},
    embeds: [{
      title: `✅ ${titleName}`,
      description: descLines.join("\n"),
      color: 3066993,
      footer: {
        text: wasQuarantined ? "Tdarr AV1 Flow • Quarantined candidate revalidated" : isFallback ? "Tdarr AV1 Flow • Seek-heal remux validated • Source video preserved" : (statusStr.includes("Compliant") ? "Tdarr AV1 Flow • Validated remux" : "Tdarr AV1 Flow • AV1 encode validated")
      },
      timestamp: new Date().toISOString()
    }]
  });

  try {
    await sendDiscordWebhook(webhookUrl, payload, {
      tag: "Discord Success Notifier",
      maxRetries: 3,
      timeoutMs: 15000,
      maxRetryDelayMs: 10000,
      maxTotalWaitMs: 30000,
      log
    });
  } catch (e) {
    log("[Discord Success Notifier] Delivery failed (unexpected error); check TDARR_DISCORD_WEBHOOK and node connectivity.");
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables
  };
};

// Reservations conservatively group all disk filesystems together and all
// memory filesystems together. They reserve the full estimate until release;
// unrelated writers, remounts, and filesystem quotas are not covered.
const reservationFs = require('fs');
const reservationPath = require('path');
const reservationCrypto = require('crypto');
const reservationOs = require('os');
const RESERVATION_DIR = '.tdarr-av1-reservations';
const RESERVATION_LOCK = '.tdarr-av1-reservations.lock';
const reservationStaleAfterMs = 15 * 60 * 1000;
let reservationPidNamespace='';
